            threadId: hired.bot.threadId ?? null,
            a01Role: hired.binding.role,
            a01Mode: hired.binding.mode,
            projectSlug: resolvedProject ?? null,
            computerProvider: resolvedProvider,
            computerLeaseId: hired.binding.computerLeaseId ?? null,
            meta: nodeMeta,
