        </form>
      </Row>
      {openAsks.length > 0 && <Row label={t("quest.part.asks")} testId="asks">
        {openAsks.map((ask) => (
          <div key={ask.id} className="flex items-start gap-1.5" data-space-ask={ask.id}>
