    expect(dryRun.stdout).toContain("xlabs-macos-base");
    expect(dryRun.stdout).toContain("xlabs-ubuntu-base");
  });
});

server/agent-computers/pool.ts:
import { randomUUID } from "node:crypto";
import {
  AGENT_COMPUTER_PROVIDERS,
  AGENT_COMPUTER_PROVIDER_CATALOG,
  buildAgentComputerName,
  computerLeaseRequestSchema,
  getProviderCatalogEntry,
  type AgentComputerProviderId,
  type CloudBurstProviderId,
  type ComputerLease,
  type ComputerLeaseRequestInput,
  type ComputerMcpEndpoint,
  type ProviderAvailability,
  type ProviderStatusWithCatalog,
} from "../../shared/agent-computers.ts";
import { DATA_DIR } from "../config.ts";
import type { DesktopComputer } from "../desktop-computer.ts";
import type { SharedComputers } from "../shared-computers.ts";
import { AgentComputerError } from "./errors.ts";
import { CuaCloudProvider } from "./providers/cua-cloud.ts";
import { DaytonaProvider } from "./providers/daytona.ts";
import { LocalCuaAxProvider } from "./providers/local-cua-ax.ts";
import { Mac2LumeVmProvider } from "./providers/mac2-lume-vm.ts";
import { Mac2SharedProvider } from "./providers/mac2-shared.ts";
import { OrgoProvider } from "./providers/orgo.ts";
import { loadAgentComputerSettings, type AgentComputerRuntimeSettings } from "./settings.ts";
import { AgentComputerStore } from "./store.ts";
import {
  defaultShellRunner,
  type ComputerProviderAdapter,
  type ExecCommandInput,
  type ExecCommandResult,
  type FetchLike,
  type ProviderContext,
  type ScreenshotPreview,
  type ShellCommandRunner,
} from "./types.ts";

export interface AgentComputerPoolOptions {
  store: AgentComputerStore;
  getSettings?: () => AgentComputerRuntimeSettings;
  fetchImpl?: FetchLike;
  runShell?: ShellCommandRunner;
  now?: () => number;
  desktop?: DesktopComputer;
  platform?: NodeJS.Platform;
  sharedComputers?: SharedComputers;
  lumeReadyPollDelaysMs?: readonly number[];
  adapters?: Partial<Record<AgentComputerProviderId, ComputerProviderAdapter>>;
}

const BURSTABLE_ERROR_CODES = new Set([
  "CAPACITY_FULL",
  "HOST_OFFLINE",
  "MISSING_CREDENTIALS",
  "UNSUPPORTED_OS",
]);

export class AgentComputerPool {
  private readonly store: AgentComputerStore;
  private readonly getSettings: () => AgentComputerRuntimeSettings;
  private readonly fetchImpl: FetchLike;
  private readonly runShell: ShellCommandRunner;
  private readonly now: () => number;
  private readonly adapters: Map<AgentComputerProviderId, ComputerProviderAdapter>;

  constructor(options: AgentComputerPoolOptions) {
    this.store = options.store;
    this.getSettings = options.getSettings ?? (() => loadAgentComputerSettings(process.env));
    this.fetchImpl = options.fetchImpl ?? globalThis.fetch;
    this.runShell = options.runShell ?? defaultShellRunner;
    this.now = options.now ?? Date.now;

    const defaults: ComputerProviderAdapter[] = [
      new Mac2LumeVmProvider({ readyPollDelaysMs: options.lumeReadyPollDelaysMs }),
      new LocalCuaAxProvider({ desktop: options.desktop, platform: options.platform }),
      new Mac2SharedProvider({ sharedComputers: options.sharedComputers }),
      new CuaCloudProvider(),
      new DaytonaProvider(),
      new OrgoProvider(),
    ];

    this.adapters = new Map();
    for (const adapter of defaults) {
      this.adapters.set(adapter.id, options.adapters?.[adapter.id] ?? adapter);
    }
  }

  getStore(): AgentComputerStore {
    return this.store;
  }

  getAdapter(id: AgentComputerProviderId): ComputerProviderAdapter {
    const adapter = this.adapters.get(id);
    if (!adapter) {
      throw new AgentComputerError(
        "INVALID_REQUEST",
        `Unknown computer provider '${id}'.`,
        `Choose one of: ${AGENT_COMPUTER_PROVIDERS.join(", ")}.`,
        400,
      );
    }
    return adapter;
  }

  private buildContext(): ProviderContext {
    return {
      settings: this.getSettings(),
      mac2Config: this.store.getMac2Config(),
      burstPolicy: this.store.getBurstPolicy(),
      activeLeases: this.store.listLeases(),
      fetchImpl: this.fetchImpl,
      runShell: this.runShell,
      now: this.now,
    };
  }

  async checkProvider(id: AgentComputerProviderId): Promise<ProviderAvailability> {
    const adapter = this.getAdapter(id);
    return adapter.checkAvailability(this.buildContext());
  }

  async listProvidersWithStatus(): Promise<ProviderStatusWithCatalog[]> {
    const context = this.buildContext();
    const results = await Promise.all(
      AGENT_COMPUTER_PROVIDER_CATALOG.map(async (catalog) => {
        const adapter = this.getAdapter(catalog.id);
        const status = await adapter.checkAvailability(context);
        return { catalog, status };
      }),
    );
    return results;
  }

  private rankBurstCandidates(input: {
    requestedProvider: AgentComputerProviderId;
    os: "macos" | "linux" | "windows";
    needsGui: boolean;
  }): CloudBurstProviderId[] {
    const policy = this.store.getBurstPolicy();
    if (!policy.enabled) return [];

    const compatible = policy.fallbackOrder.filter((candidate) => {
      if (candidate === input.requestedProvider) return false;
      const meta = getProviderCatalogEntry(candidate);
      return meta.supportedOs.includes(input.os);
    });

    if (input.os === "linux" && !input.needsGui && policy.preferDaytonaForHeadlessLinux) {
      return [
        ...compatible.filter((id) => id === "daytona"),
        ...compatible.filter((id) => id !== "daytona"),
      ];
    }

    if (input.needsGui) {
      return [
        ...compatible.filter((id) => getProviderCatalogEntry(id).supportsGui),
        ...compatible.filter((id) => !getProviderCatalogEntry(id).supportsGui),
      ];
    }

    return compatible;
  }

  /**
   * Provisions or attaches an isolated computer for an agent.
   * Defaults to `mac2-lume-vm` (#1 Primary Dedicated Computer) and bursts to cloud when full or offline.
   */
  async acquireComputer(rawRequest: ComputerLeaseRequestInput): Promise<ComputerLease> {
    const request = computerLeaseRequestSchema.parse(rawRequest);
    const requestedProvider: AgentComputerProviderId = request.preferredProvider ?? "mac2-lume-vm";

    const existingRunning = this.store
      .listLeases({ agentId: request.agentId })
      .find(
        (lease) =>
          lease.state === "running" &&
          lease.mode === request.mode &&
          lease.os === request.os &&
          (request.preferredProvider === undefined ||
            lease.requestedProvider === requestedProvider ||
            lease.provider === requestedProvider),
      );
    if (existingRunning) {
      const refreshed: ComputerLease = {
        ...existingRunning,
        updatedAt: this.now(),
        lastUsedAt: this.now(),
      };
      return this.store.upsertLease(refreshed);
    }

    const context = this.buildContext();
    const primaryAdapter = this.getAdapter(requestedProvider);

    try {
      const provisioned = await primaryAdapter.provisionOrLease(request, context);
      return this.recordProvisionedLease({
        request,
        provider: requestedProvider,
        requestedProvider,
        burstedFrom: null,
        provisioned,
      });
    } catch (primaryError) {
      const canBurst =
        request.allowCloudBurst &&
        this.store.getBurstPolicy().enabled &&
        primaryError instanceof AgentComputerError &&
        BURSTABLE_ERROR_CODES.has(primaryError.code);

      if (!canBurst) {
        throw primaryError;
      }

      const candidates = this.rankBurstCandidates({
        requestedProvider,
        os: request.os,
        needsGui: request.needsGui,
      });

      const fallbackDiagnostics: string[] = [];
      for (const candidateId of candidates) {
        const candidateAdapter = this.getAdapter(candidateId);
        const availability = await candidateAdapter.checkAvailability(context);
        if (!availability.available) {
          fallbackDiagnostics.push(`${candidateId}: ${availability.reasonCode}`);
          continue;
        }
        try {
          const provisioned = await candidateAdapter.provisionOrLease(request, context);
          return this.recordProvisionedLease({
            request,
            provider: candidateId,
            requestedProvider,
            burstedFrom: requestedProvider,
            provisioned,
          });
        } catch (burstError) {
          fallbackDiagnostics.push(
            `${candidateId}: ${burstError instanceof Error ? burstError.message : String(burstError)}`,
          );
        }
      }

      const primaryErr = primaryError as AgentComputerError;
      const fallbackSummary =
        fallbackDiagnostics.length > 0
          ? ` Burst candidates unavailable (${fallbackDiagnostics.join("; ")}).`
          : " No OS-compatible Cloud Burst providers enabled.";

      throw new AgentComputerError(
        primaryErr.code,
        `${primaryErr.message}${fallbackSummary}`,
        primaryErr.next,
        primaryErr.status,
      );
    }
  }

  private recordProvisionedLease(input: {
    request: ReturnType<typeof computerLeaseRequestSchema.parse>;
    provider: AgentComputerProviderId;
    requestedProvider: AgentComputerProviderId;
    burstedFrom: AgentComputerProviderId | null;
    provisioned: {
      instanceId: string;
      instanceName: string;
      os: "macos" | "linux" | "windows";
      state: "provisioning" | "running" | "paused" | "stopped" | "destroyed" | "error";
      guestIp?: string | null;
      vncPreviewUrl?: string | null;
      snapshotName?: string | null;
    };
  }): ComputerLease {
    const at = this.now();
    const expectedName = buildAgentComputerName(input.request);
    const previousPersistent =
      input.request.mode === "long-term"
        ? this.store.findPersistentLease({
            provider: input.provider,
            instanceName: input.provisioned.instanceName || expectedName,
          })
        : null;

    const lease: ComputerLease = {
      leaseId: previousPersistent?.leaseId ?? randomUUID(),
      agentId: input.request.agentId,
      provider: input.provider,
      requestedProvider: input.requestedProvider,
      burstedFrom: input.burstedFrom,
      mode: input.request.mode,
      os: input.provisioned.os,
      ...(input.request.role ? { role: input.request.role } : {}),
      ...(input.request.project ? { project: input.request.project } : {}),
      instanceId: input.provisioned.instanceId,
      instanceName: input.provisioned.instanceName,
      state: input.provisioned.state,
      guestIp: input.provisioned.guestIp ?? null,
      vncPreviewUrl: input.provisioned.vncPreviewUrl ?? null,
      snapshotName: input.provisioned.snapshotName ?? previousPersistent?.snapshotName ?? null,
      createdAt: previousPersistent?.createdAt ?? at,
      updatedAt: at,
      lastUsedAt: at,
    };

    return this.store.upsertLease(lease);
  }

  private requireLease(leaseId: string): ComputerLease {
    const lease = this.store.getLease(leaseId);
    if (!lease || lease.state === "destroyed") {
      throw new AgentComputerError(
        "LEASE_NOT_FOUND",
        `Computer lease '${leaseId}' does not exist or was already destroyed.`,
        "Acquire a new computer lease via pool.acquireComputer().",
        404,
      );
    }
    return lease;
  }

  async execCommand(leaseId: string, input: ExecCommandInput): Promise<ExecCommandResult> {
    const lease = this.requireLease(leaseId);
    if (lease.state !== "running") {
      throw new AgentComputerError(
        "INVALID_REQUEST",
        `Cannot execute command on lease '${leaseId}' while state is '${lease.state}'.`,
        "Re-acquire or wake the computer lease before executing commands.",
      );
    }
    const adapter = this.getAdapter(lease.provider);
    const result = await adapter.execCommand(lease, input, this.buildContext());
    this.store.upsertLease({
      ...lease,
      updatedAt: this.now(),
      lastUsedAt: this.now(),
    });
    return result;
  }

  async getMcpEndpoint(leaseId: string): Promise<ComputerMcpEndpoint | null> {
    const lease = this.requireLease(leaseId);
    if (lease.state !== "running") return null;
    const adapter = this.getAdapter(lease.provider);
    return adapter.mcpEndpoint(lease, this.buildContext());
  }

  async screenshotPreview(leaseId: string): Promise<ScreenshotPreview> {
    const lease = this.requireLease(leaseId);
    if (lease.state !== "running") {
      throw new AgentComputerError(
        "INVALID_REQUEST",
        `Cannot capture screenshot on lease '${leaseId}' while state is '${lease.state}'.`,
        "Wake the computer lease first.",
      );
    }
    const adapter = this.getAdapter(lease.provider);
    return adapter.screenshotPreview(lease, this.buildContext());
  }

  /**
   * Lifecycle-aware session close:
   * - `temporary` -> destroys & wipes ephemeral VM (`tmp-<agentId>`)
   * - `long-term` -> snapshots & stops persistent VM (`a01-<role>-<project>`)
   */
  async closeSession(leaseId: string): Promise<ComputerLease> {
    const lease = this.requireLease(leaseId);
    if (lease.mode === "temporary") {
      return this.destroyLease(leaseId);
    }
    return this.pauseOrStopLease(leaseId);
  }

  async pauseOrStopLease(leaseId: string): Promise<ComputerLease> {
    const lease = this.requireLease(leaseId);
    const adapter = this.getAdapter(lease.provider);
    const outcome = await adapter.pauseOrStop(lease, this.buildContext());
    return this.store.upsertLease({
      ...lease,
      state: outcome.state,
      snapshotName: outcome.snapshotName !== undefined ? outcome.snapshotName : lease.snapshotName,
      updatedAt: this.now(),
    });
  }

  async destroyLease(leaseId: string): Promise<ComputerLease> {
    const lease = this.requireLease(leaseId);
    const adapter = this.getAdapter(lease.provider);
    const outcome = await adapter.destroyLease(lease, this.buildContext());
    return this.store.upsertLease({
      ...lease,
      state: outcome.state,
      snapshotName: null,
      updatedAt: this.now(),
    });
  }
}

export function createDefaultAgentComputerPool(options: {
  dataDir?: string;
  desktop?: DesktopComputer;
  sharedComputers?: SharedComputers;
} = {}): AgentComputerPool {
  const store = new AgentComputerStore(options.dataDir ?? DATA_DIR);
  return new AgentComputerPool({
    store,
    desktop: options.desktop,
    sharedComputers: options.sharedComputers,
  });
}

server/agent-computers/providers/cua-clo:
import {
  buildAgentComputerName,
  type ComputerLease,
  type ComputerLeaseRequest,
  type ComputerMcpEndpoint,
  type ProviderAvailability,
} from "../../../shared/agent-computers.ts";
import { AgentComputerError } from "../errors.ts";
import type {
  ComputerProviderAdapter,
  ExecCommandInput,
  ExecCommandResult,
  LeaseLifecycleResult,
  ProviderContext,
  ProvisionedComputer,
  ScreenshotPreview,
} from "../types.ts";

interface CuaCloudSpaceRecord {
  id?: string;
  name?: string;
  status?: string;
  state?: string;
  os?: string;
  ip?: string | null;
  vncUrl?: string | null;
  streamUrl?: string | null;
}

export interface CuaCloudProviderOptions {
  maxCapacity?: number;
}

export class CuaCloudProvider implements ComputerProviderAdapter {
  readonly id = "cua-cloud" as const;
  private readonly maxCapacity: number;

  constructor(options: CuaCloudProviderOptions = {}) {
    this.maxCapacity = options.maxCapacity ?? 50;
  }

  private requireApiKey(context: ProviderContext): string {
    const key = context.settings.cuaApiKey;
    if (!key) {
      throw new AgentComputerError(
        "MISSING_CREDENTIALS",
        "CUA_API_KEY is missing from runtime environment.",
        "Inject CUA_API_KEY via Bitwarden Secrets Manager: keys run stable -- pnpm dev:server",
      );
    }
    return key;
  }

  private async apiJson(
    context: ProviderContext,
    method: "GET" | "POST" | "DELETE",
    path: string,
    payload?: Record<string, unknown>,
  ): Promise<{ ok: boolean; status: number; body: unknown }> {
    const key = this.requireApiKey(context);
    const response = await context.fetchImpl(`${context.settings.cuaApiBaseUrl}${path}`, {
      method,
      headers: {
        authorization: `Bearer ${key}`,
        ...(payload ? { "content-type": "application/json" } : {}),
      },
      body: payload ? JSON.stringify(payload) : undefined,
      signal: AbortSignal.timeout(30_000),
    });
    const text = await response.text();
    let body: unknown = null;
    if (text.trim()) {
      try {
        body = JSON.parse(text);
      } catch {
        body = text;
      }
    }
    return { ok: response.ok, status: response.status, body };
  }

  async checkAvailability(context: ProviderContext): Promise<ProviderAvailability> {
    const activeLeases = context.activeLeases.filter(
      (lease) => lease.provider === this.id && lease.state === "running",
    ).length;

    if (!context.settings.cuaApiKey) {
      return {
        provider: this.id,
        available: false,
        state: "missing_credentials",
        reasonCode: "missing_api_key",
        message: "CUA_API_KEY is not set in environment.",
        nextStep: "Inject CUA_API_KEY at runtime via: keys run stable -- pnpm dev:server",
        activeLeases,
        maxCapacity: this.maxCapacity,
        supportedOs: ["macos", "linux", "windows"],
        checkedAt: context.now(),
      };
    }

    try {
      const res = await this.apiJson(context, "GET", "/spaces");
      if (res.status === 401 || res.status === 403) {
        return {
          provider: this.id,
          available: false,
          state: "missing_credentials",
          reasonCode: "auth_rejected",
          message: "Cua Cloud rejected CUA_API_KEY (HTTP 401/403).",
          nextStep: "Verify or rotate CUA_API_KEY in Bitwarden Secrets Manager.",
          activeLeases,
          maxCapacity: this.maxCapacity,
          supportedOs: ["macos", "linux", "windows"],
          checkedAt: context.now(),
        };
      }
      if (!res.ok) {
        return {
          provider: this.id,
          available: false,
          state: "degraded",
          reasonCode: "provider_error",
          message: `Cua Cloud status check returned HTTP ${res.status}.`,
          nextStep: "Check https://cua.ai service status or CUA_API_URL.",
          activeLeases,
          maxCapacity: this.maxCapacity,
          supportedOs: ["macos", "linux", "windows"],
          checkedAt: context.now(),
        };
      }
      return {
        provider: this.id,
        available: activeLeases < this.maxCapacity,
        state: activeLeases < this.maxCapacity ? "ready" : "capacity_full",
        reasonCode: activeLeases < this.maxCapacity ? "ok" : "capacity_full",
        message: "Cua.ai Cloud Spaces ready (macOS, Linux, Windows).",
        nextStep: null,
        activeLeases,
        maxCapacity: this.maxCapacity,
        supportedOs: ["macos", "linux", "windows"],
        checkedAt: context.now(),
      };
    } catch (error) {
      return {
        provider: this.id,
        available: false,
        state: "host_offline",
        reasonCode: "host_offline",
        message: `Could not reach Cua Cloud API: ${error instanceof Error ? error.message : String(error)}`,
        nextStep: "Check network connectivity to api.cua.ai.",
        activeLeases,
        maxCapacity: this.maxCapacity,
        supportedOs: ["macos", "linux", "windows"],
        checkedAt: context.now(),
      };
    }
  }

  private extractSpaces(raw: unknown): CuaCloudSpaceRecord[] {
    if (Array.isArray(raw)) return raw as CuaCloudSpaceRecord[];
    if (raw && typeof raw === "object" && Array.isArray((raw as { spaces?: unknown }).spaces)) {
      return (raw as { spaces: CuaCloudSpaceRecord[] }).spaces;
    }
    return [];
  }

  async provisionOrLease(
    request: ComputerLeaseRequest,
    context: ProviderContext,
  ): Promise<ProvisionedComputer> {
    this.requireApiKey(context);
    const spaceName = buildAgentComputerName(request);

    if (request.mode === "long-term") {
      const listed = await this.apiJson(context, "GET", "/spaces");
      if (listed.ok) {
        const existing = this.extractSpaces(listed.body).find(
          (item) => item.name === spaceName && typeof item.id === "string",
        );
        if (existing && existing.id) {
          const currentState = (existing.status ?? existing.state ?? "").toLowerCase();
          if (currentState !== "running" && currentState !== "ready") {
            const started = await this.apiJson(
              context,
              "POST",
              `/spaces/${encodeURIComponent(existing.id)}/start`,
              {},
            );
            if (!started.ok && started.status !== 409) {
              throw new AgentComputerError(
                "PROVIDER_ERROR",
                `Failed to wake Cua Cloud Space '${spaceName}' (HTTP ${started.status}).`,
                "Check Space status in Cua Cloud console.",
                502,
              );
            }
          }
          return {
            instanceId: existing.id,
            instanceName: spaceName,
            os: request.os,
            state: "running",
            guestIp: existing.ip ?? null,
            vncPreviewUrl: existing.vncUrl ?? existing.streamUrl ?? null,
          };
        }
      }
    }

    const created = await this.apiJson(context, "POST", "/spaces", {
      name: spaceName,
      os: request.os,
      persistent: request.mode === "long-term",
      ephemeral: request.mode === "temporary",
      cpu: request.cpuCores ?? 4,
      memoryGb: request.memoryGb ?? 8,
    });
    if (!created.ok || !created.body || typeof created.body !== "object") {
      throw new AgentComputerError(
        created.status === 401 || created.status === 403 ? "MISSING_CREDENTIALS" : "PROVIDER_ERROR",
        `Cua Cloud failed to provision Space '${spaceName}' (HTTP ${created.status}).`,
        "Check CUA_API_KEY quota and requested OS availability.",
        created.status >= 400 && created.status < 600 ? created.status : 502,
      );
    }

    const record = ((created.body as { space?: CuaCloudSpaceRecord }).space ??
      created.body) as CuaCloudSpaceRecord;
    const spaceId = record.id ?? spaceName;
    return {
      instanceId: spaceId,
      instanceName: record.name ?? spaceName,
      os: request.os,
      state: "running",
      guestIp: record.ip ?? null,
      vncPreviewUrl: record.vncUrl ?? record.streamUrl ?? null,
    };
  }

  async execCommand(
    lease: ComputerLease,
    input: ExecCommandInput,
    context: ProviderContext,
  ): Promise<ExecCommandResult> {
    const startedAt = context.now();
    const res = await this.apiJson(
      context,
      "POST",
      `/spaces/${encodeURIComponent(lease.instanceId)}/commands`,
      {
        command: input.command,
        ...(input.cwd ? { cwd: input.cwd } : {}),
        timeoutMs: input.timeoutMs ?? 60_000,
      },
    );
    if (!res.ok) {
      throw new AgentComputerError(
        "COMMAND_FAILED",
        `Cua Cloud command failed on Space '${lease.instanceId}' (HTTP ${res.status}).`,
        "Verify the Cua Cloud Space is still running.",
      );
    }
    const payload = (res.body && typeof res.body === "object" ? res.body : {}) as {
      exitCode?: number;
      stdout?: string;
      stderr?: string;
    };
    const exitCode = typeof payload.exitCode === "number" ? payload.exitCode : 0;
    return {
      ok: exitCode === 0,
      exitCode,
      stdout: payload.stdout ?? "",
      stderr: payload.stderr ?? "",
      durationMs: Math.max(0, context.now() - startedAt),
    };
  }

  async mcpEndpoint(lease: ComputerLease, context: ProviderContext): Promise<ComputerMcpEndpoint | null> {
    const key = context.settings.cuaApiKey;
    if (!key) return null;
    return {
      kind: "streamable-http",
      toolSurface: "cua-driver",
      url: `${context.settings.cuaApiBaseUrl}/spaces/${encodeURIComponent(lease.instanceId)}/mcp`,
      headers: {
        authorization: `Bearer ${key}`,
      },
      env: {
        CUA_SPACE_ID: lease.instanceId,
      },
    };
  }

  async screenshotPreview(
    lease: ComputerLease,
    context: ProviderContext,
  ): Promise<ScreenshotPreview> {
    const res = await this.apiJson(
      context,
      "GET",
      `/spaces/${encodeURIComponent(lease.instanceId)}/screenshot`,
    );
    if (!res.ok) {
      throw new AgentComputerError(
        "COMMAND_FAILED",
        `Cua Cloud screenshot failed on '${lease.instanceId}' (HTTP ${res.status}).`,
        "Check that the Cua Cloud Space desktop session is active.",
      );
    }
    const payload = (res.body && typeof res.body === "object" ? res.body : {}) as {
      data?: string;
      image?: string;
      base64?: string;
      mimeType?: string;
    };
    return {
      mimeType: payload.mimeType === "image/jpeg" ? "image/jpeg" : "image/png",
      base64Data: payload.data ?? payload.image ?? payload.base64 ?? "",
      vncPreviewUrl: lease.vncPreviewUrl,
      capturedAt: context.now(),
    };
  }

  async pauseOrStop(
    lease: ComputerLease,
    context: ProviderContext,
  ): Promise<LeaseLifecycleResult> {
    const res = await this.apiJson(
      context,
      "POST",
      `/spaces/${encodeURIComponent(lease.instanceId)}/stop`,
      {},
    );
    if (!res.ok && res.status !== 404 && res.status !== 409) {
      throw new AgentComputerError(
        "PROVIDER_ERROR",
        `Failed to stop Cua Cloud Space '${lease.instanceId}' (HTTP ${res.status}).`,
        "Retry stopping the Space or inspect Cua Cloud console.",
        502,
      );
    }
    return {
      state: "stopped",
      detail: `Stopped Cua Cloud Space '${lease.instanceId}'.`,
    };
  }

  async destroyLease(
    lease: ComputerLease,
    context: ProviderContext,
  ): Promise<LeaseLifecycleResult> {
    const res = await this.apiJson(
      context,
      "DELETE",
      `/spaces/${encodeURIComponent(lease.instanceId)}`,
    );
    if (!res.ok && res.status !== 404 && res.status !== 410) {
      throw new AgentComputerError(
        "PROVIDER_ERROR",
        `Failed to delete Cua Cloud Space '${lease.instanceId}' (HTTP ${res.status}).`,
        "Verify Space deletion in Cua Cloud console.",
        502,
      );
    }
    return {
      state: "destroyed",
      detail: `Deleted Cua Cloud Space '${lease.instanceId}'.`,
    };
  }
}

server/agent-computers/providers/daytona:
import {
  buildAgentComputerName,
  type ComputerLease,
  type ComputerLeaseRequest,
  type ComputerMcpEndpoint,
  type ProviderAvailability,
} from "../../../shared/agent-computers.ts";
import { AgentComputerError } from "../errors.ts";
import type {
  ComputerProviderAdapter,
  ExecCommandInput,
  ExecCommandResult,
  LeaseLifecycleResult,
  ProviderContext,
  ProvisionedComputer,
  ScreenshotPreview,
} from "../types.ts";

interface DaytonaSandboxRecord {
  id?: string;
  name?: string;
  state?: string;
  status?: string;
}

export interface DaytonaProviderOptions {
  maxCapacity?: number;
}

export class DaytonaProvider implements ComputerProviderAdapter {
  readonly id = "daytona" as const;
  private readonly maxCapacity: number;

  constructor(options: DaytonaProviderOptions = {}) {
    this.maxCapacity = options.maxCapacity ?? 100;
  }

  private requireApiKey(context: ProviderContext): string {
    const key = context.settings.daytonaApiKey;
    if (!key) {
      throw new AgentComputerError(
        "MISSING_CREDENTIALS",
        "DAYTONA_API_KEY is missing from runtime environment.",
        "Inject DAYTONA_API_KEY via Bitwarden Secrets Manager: keys run stable -- pnpm dev:server",
      );
    }
    return key;
  }

  private async apiJson(
    context: ProviderContext,
    method: "GET" | "POST" | "DELETE",
    path: string,
    payload?: Record<string, unknown>,
  ): Promise<{ ok: boolean; status: number; body: unknown }> {
    const key = this.requireApiKey(context);
    const response = await context.fetchImpl(`${context.settings.daytonaApiBaseUrl}${path}`, {
      method,
      headers: {
        authorization: `Bearer ${key}`,
        ...(payload ? { "content-type": "application/json" } : {}),
      },
      body: payload ? JSON.stringify(payload) : undefined,
      signal: AbortSignal.timeout(25_000),
    });
    const text = await response.text();
    let body: unknown = null;
    if (text.trim()) {
      try {
        body = JSON.parse(text);
      } catch {
        body = text;
      }
    }
    return { ok: response.ok, status: response.status, body };
  }

  async checkAvailability(context: ProviderContext): Promise<ProviderAvailability> {
    const activeLeases = context.activeLeases.filter(
      (lease) => lease.provider === this.id && lease.state === "running",
    ).length;

    if (!context.settings.daytonaApiKey) {
      return {
        provider: this.id,
        available: false,
        state: "missing_credentials",
        reasonCode: "missing_api_key",
        message: "DAYTONA_API_KEY is not set in environment.",
        nextStep: "Inject DAYTONA_API_KEY at runtime via: keys run stable -- pnpm dev:server",
        activeLeases,
        maxCapacity: this.maxCapacity,
        supportedOs: ["linux"],
        checkedAt: context.now(),
      };
    }

    try {
      const res = await this.apiJson(context, "GET", "/sandbox");
      if (res.status === 401 || res.status === 403) {
        return {
          provider: this.id,
          available: false,
          state: "missing_credentials",
          reasonCode: "auth_rejected",
          message: "Daytona rejected DAYTONA_API_KEY (HTTP 401/403).",
          nextStep: "Rotate DAYTONA_API_KEY in Bitwarden Secrets Manager.",
          activeLeases,
          maxCapacity: this.maxCapacity,
          supportedOs: ["linux"],
          checkedAt: context.now(),
        };
      }
      if (!res.ok) {
        return {
          provider: this.id,
          available: false,
          state: "degraded",
          reasonCode: "provider_error",
          message: `Daytona status check returned HTTP ${res.status}.`,
          nextStep: "Check https://app.daytona.io status.",
          activeLeases,
          maxCapacity: this.maxCapacity,
          supportedOs: ["linux"],
          checkedAt: context.now(),
        };
      }
      return {
        provider: this.id,
        available: activeLeases < this.maxCapacity,
        state: activeLeases < this.maxCapacity ? "ready" : "capacity_full",
        reasonCode: activeLeases < this.maxCapacity ? "ok" : "capacity_full",
        message: "Daytona sub-second Linux sandboxes ready (~$0.05/vCPU-hr).",
        nextStep: null,
        activeLeases,
        maxCapacity: this.maxCapacity,
        supportedOs: ["linux"],
        checkedAt: context.now(),
      };
    } catch (error) {
      return {
        provider: this.id,
        available: false,
        state: "host_offline",
        reasonCode: "host_offline",
        message: `Could not reach Daytona API: ${error instanceof Error ? error.message : String(error)}`,
        nextStep: "Check network connectivity to app.daytona.io.",
        activeLeases,
        maxCapacity: this.maxCapacity,
        supportedOs: ["linux"],
        checkedAt: context.now(),
      };
    }
  }

  private extractSandboxes(raw: unknown): DaytonaSandboxRecord[] {
    if (Array.isArray(raw)) return raw as DaytonaSandboxRecord[];
    if (raw && typeof raw === "object" && Array.isArray((raw as { items?: unknown }).items)) {
      return (raw as { items: DaytonaSandboxRecord[] }).items;
    }
    return [];
  }

  async provisionOrLease(
    request: ComputerLeaseRequest,
    context: ProviderContext,
  ): Promise<ProvisionedComputer> {
    if (request.os !== "linux") {
      throw new AgentComputerError(
        "UNSUPPORTED_OS",
        `Daytona supports Linux sandboxes only, cannot satisfy OS '${request.os}'.`,
        "Use mac2-lume-vm or cua-cloud for macOS/Windows.",
        400,
      );
    }

    this.requireApiKey(context);
    const sandboxName = buildAgentComputerName(request);

    if (request.mode === "long-term") {
      const listed = await this.apiJson(context, "GET", "/sandbox");
      if (listed.ok) {
        const existing = this.extractSandboxes(listed.body).find(
          (item) => item.name === sandboxName && typeof item.id === "string",
        );
        if (existing && existing.id) {
          const state = (existing.state ?? existing.status ?? "").toLowerCase();
          if (state !== "started" && state !== "running") {
            const started = await this.apiJson(
              context,
              "POST",
              `/sandbox/${encodeURIComponent(existing.id)}/start`,
              {},
            );
            if (!started.ok && started.status !== 409) {
              throw new AgentComputerError(
                "PROVIDER_ERROR",
                `Failed to start Daytona sandbox '${sandboxName}' (HTTP ${started.status}).`,
                "Inspect sandbox state in Daytona dashboard.",
                502,
              );
            }
          }
          return {
            instanceId: existing.id,
            instanceName: sandboxName,
            os: "linux",
            state: "running",
          };
        }
      }
    }

    const created = await this.apiJson(context, "POST", "/sandbox", {
      name: sandboxName,
      snapshot: "default",
      cpu: request.cpuCores ?? 2,
      memory: request.memoryGb ?? 4,
      disk: 10,
      ephemeral: request.mode === "temporary",
      autoStopInterval: request.mode === "long-term" ? 30 : 15,
      labels: {
        "xlabs.mode": request.mode,
        "xlabs.agent": request.agentId,
      },
    });
    if (!created.ok || !created.body || typeof created.body !== "object") {
      throw new AgentComputerError(
        created.status === 401 || created.status === 403 ? "MISSING_CREDENTIALS" : "PROVIDER_ERROR",
        `Daytona failed to create sandbox '${sandboxName}' (HTTP ${created.status}).`,
        "Verify DAYTONA_API_KEY and organization sandbox limits.",
        created.status >= 400 && created.status < 600 ? created.status : 502,
      );
    }

    const record = created.body as DaytonaSandboxRecord;
    return {
      instanceId: record.id ?? sandboxName,
      instanceName: record.name ?? sandboxName,
      os: "linux",
      state: "running",
    };
  }

  async execCommand(
    lease: ComputerLease,
    input: ExecCommandInput,
    context: ProviderContext,
  ): Promise<ExecCommandResult> {
    const startedAt = context.now();
    const id = encodeURIComponent(lease.instanceId);
    const payload = {
      command: input.command,
      ...(input.cwd ? { cwd: input.cwd } : {}),
      timeout: Math.ceil((input.timeoutMs ?? 60_000) / 1000),
    };

    let res = await this.apiJson(context, "POST", `/sandbox/${id}/toolbox/process/execute`, payload);
    if (res.status === 404) {
      res = await this.apiJson(context, "POST", `/sandbox/${id}/process/execute`, payload);
    }
    if (!res.ok) {
      throw new AgentComputerError(
        "COMMAND_FAILED",
        `Daytona command execution failed on '${lease.instanceId}' (HTTP ${res.status}).`,
        "Verify the Daytona sandbox is in 'started' state.",
      );
    }

    const body = (res.body && typeof res.body === "object" ? res.body : {}) as {
      exitCode?: number;
      code?: number;
      result?: string;
      stdout?: string;
      stderr?: string;
    };
    const exitCode =
      typeof body.exitCode === "number"
        ? body.exitCode
        : typeof body.code === "number"
          ? body.code
          : 0;

    return {
      ok: exitCode === 0,
      exitCode,
      stdout: body.stdout ?? body.result ?? "",
      stderr: body.stderr ?? "",
      durationMs: Math.max(0, context.now() - startedAt),
    };
  }

  async mcpEndpoint(lease: ComputerLease, context: ProviderContext): Promise<ComputerMcpEndpoint | null> {
    const key = context.settings.daytonaApiKey;
    if (!key) return null;
    return {
      kind: "rest-bridge",
      toolSurface: "daytona-exec",
      url: `${context.settings.daytonaApiBaseUrl}/sandbox/${encodeURIComponent(lease.instanceId)}`,
      headers: {
        authorization: `Bearer ${key}`,
      },
      env: {
        DAYTONA_SANDBOX_ID: lease.instanceId,
      },
    };
  }

  async screenshotPreview(
    lease: ComputerLease,
    context: ProviderContext,
  ): Promise<ScreenshotPreview> {
    const capture = await this.execCommand(
      lease,
      {
        command:
          "if command -v import >/dev/null 2>&1 && [ -n \"${DISPLAY:-}\" ]; then import -window root png:- | base64 | tr -d '\\n'; else exit 2; fi",
        timeoutMs: 10_000,
      },
      context,
    );
    if (!capture.ok || !capture.stdout.trim()) {
      throw new AgentComputerError(
        "COMMAND_FAILED",
        `Daytona sandbox '${lease.instanceId}' has no active X11 GUI display for screenshots.`,
        "Use orgo, cua-cloud, or mac2-lume-vm when full GUI desktop screenshots are required.",
      );
    }
    return {
      mimeType: "image/png",
      base64Data: capture.stdout.trim(),
      vncPreviewUrl: null,
      capturedAt: context.now(),
    };
  }

  async pauseOrStop(
    lease: ComputerLease,
    context: ProviderContext,
  ): Promise<LeaseLifecycleResult> {
    const res = await this.apiJson(
      context,
      "POST",
      `/sandbox/${encodeURIComponent(lease.instanceId)}/stop`,
      {},
    );
    if (!res.ok && res.status !== 404 && res.status !== 409) {
      throw new AgentComputerError(
        "PROVIDER_ERROR",
        `Failed to stop Daytona sandbox '${lease.instanceId}' (HTTP ${res.status}).`,
        "Inspect sandbox status in Daytona dashboard.",
        502,
      );
    }
    return {
      state: "stopped",
      detail: `Stopped Daytona sandbox '${lease.instanceId}'.`,
    };
  }

  async destroyLease(
    lease: ComputerLease,
    context: ProviderContext,
  ): Promise<LeaseLifecycleResult> {
    const res = await this.apiJson(
      context,
      "DELETE",
      `/sandbox/${encodeURIComponent(lease.instanceId)}`,
    );
    if (!res.ok && res.status !== 404 && res.status !== 410) {
      throw new AgentComputerError(
        "PROVIDER_ERROR",
        `Failed to delete Daytona sandbox '${lease.instanceId}' (HTTP ${res.status}).`,
        "Delete the sandbox manually in Daytona dashboard.",
        502,
      );
    }
    return {
      state: "destroyed",
      detail: `Deleted Daytona sandbox '${lease.instanceId}'.`,
    };
  }
}

server/agent-computers/providers/local-c:
import type {
  ComputerLease,
  ComputerLeaseRequest,
  ComputerMcpEndpoint,
  ComputerOsFamily,
  ProviderAvailability,
} from "../../../shared/agent-computers.ts";
import { desktopComputer, thisComputerNotReady, type DesktopComputer } from "../../desktop-computer.ts";
import { AgentComputerError } from "../errors.ts";
import {
  buildCleanRemoteShellCommand,
  type ComputerProviderAdapter,
  type ExecCommandInput,
  type ExecCommandResult,
  type LeaseLifecycleResult,
  type ProviderContext,
  type ProvisionedComputer,
  type ScreenshotPreview,
} from "../types.ts";

export interface LocalCuaAxProviderOptions {
  desktop?: DesktopComputer;
  platform?: NodeJS.Platform;
  maxCapacity?: number;
}

function platformToOs(platform: NodeJS.Platform): ComputerOsFamily {
  if (platform === "darwin") return "macos";
  if (platform === "win32") return "windows";
  return "linux";
}

function extractSocketPath(args: readonly string[]): string | null {
  const index = args.indexOf("--socket");
  if (index >= 0 && index + 1 < args.length) {
    return args[index + 1] ?? null;
  }
  return null;
}

export class LocalCuaAxProvider implements ComputerProviderAdapter {
  readonly id = "local-cua-ax" as const;
  private readonly desktop: DesktopComputer;
  private readonly platform: NodeJS.Platform;
  private readonly maxCapacity: number;

  constructor(options: LocalCuaAxProviderOptions = {}) {
    this.desktop = options.desktop ?? desktopComputer;
    this.platform = options.platform ?? process.platform;
    this.maxCapacity = options.maxCapacity ?? 4;
  }

  async checkAvailability(context: ProviderContext): Promise<ProviderAvailability> {
    const hostOs = platformToOs(this.platform);
    const activeLeases = context.activeLeases.filter(
      (lease) => lease.provider === this.id && lease.state === "running",
    ).length;

    const granted = this.desktop.granted();
    const connection = granted ? this.desktop.connection() : null;
    if (!granted || !connection) {
      return {
        provider: this.id,
        available: false,
        state: "host_offline",
        reasonCode: "desktop_not_granted",
        message: thisComputerNotReady(this.desktop, this.platform),
        nextStep:
          "Open the OpenMausBot desktop app on this Mac and grant Accessibility + Screen Recording in System Settings → Privacy & Security.",
        activeLeases,
        maxCapacity: this.maxCapacity,
        supportedOs: [hostOs],
        checkedAt: context.now(),
      };
    }

    if (activeLeases >= this.maxCapacity) {
      return {
        provider: this.id,
        available: false,
        state: "capacity_full",
        reasonCode: "capacity_full",
        message: `Local Cua AX driver is at capacity (${activeLeases}/${this.maxCapacity} active agents).`,
        nextStep: "Route additional concurrent agents to mac2-lume-vm or allow Cloud Burst.",
        activeLeases,
        maxCapacity: this.maxCapacity,
        supportedOs: [hostOs],
        checkedAt: context.now(),
      };
    }

    return {
      provider: this.id,
      available: true,
      state: "ready",
      reasonCode: "ok",
      message: "Local Cua AX background driver is ready on this computer.",
      nextStep: null,
      activeLeases,
      maxCapacity: this.maxCapacity,
      supportedOs: [hostOs],
      checkedAt: context.now(),
    };
  }

  async provisionOrLease(
    request: ComputerLeaseRequest,
    context: ProviderContext,
  ): Promise<ProvisionedComputer> {
    const hostOs = platformToOs(this.platform);
    if (request.os !== hostOs) {
      throw new AgentComputerError(
        "UNSUPPORTED_OS",
        `Local Cua AX runs on ${hostOs}, cannot satisfy requested OS ${request.os}.`,
        "Use mac2-lume-vm for macOS/Linux VMs or cua-cloud for Windows.",
        400,
      );
    }
    const availability = await this.checkAvailability(context);
    if (!availability.available) {
      throw new AgentComputerError(
        availability.state === "capacity_full" ? "CAPACITY_FULL" : "HOST_OFFLINE",
        availability.message,
        availability.nextStep ?? "Open OpenMausBot desktop on this Mac.",
      );
    }
    return {
      instanceId: "local-cua-ax-host",
      instanceName: "This Mac (Background AX)",
      os: hostOs,
      state: "running",
      guestIp: "127.0.0.1",
      vncPreviewUrl: null,
    };
  }

  async execCommand(
    _lease: ComputerLease,
    input: ExecCommandInput,
    context: ProviderContext,
  ): Promise<ExecCommandResult> {
    const startedAt = context.now();
    const wrapped = buildCleanRemoteShellCommand(input.command, input.cwd);
    const out = await context.runShell("/bin/sh", ["-c", wrapped], {
      timeoutMs: input.timeoutMs,
    });
    return {
      ok: out.exitCode === 0,
      exitCode: out.exitCode,
      stdout: out.stdout,
      stderr: out.stderr,
      durationMs: Math.max(0, context.now() - startedAt),
    };
  }

  async mcpEndpoint(_lease: ComputerLease, _context: ProviderContext): Promise<ComputerMcpEndpoint | null> {
    const connection = this.desktop.connection();
    if (!connection) return null;
    return {
      kind: "stdio",
      toolSurface: "cua-driver",
      command: connection.command,
      args: [...connection.args],
      env: { ...connection.env },
    };
  }

  async screenshotPreview(
    _lease: ComputerLease,
    context: ProviderContext,
  ): Promise<ScreenshotPreview> {
    const connection = this.desktop.connection();
    if (!connection) {
      throw new AgentComputerError(
        "HOST_OFFLINE",
        "Local Cua Driver socket is not connected.",
        "Open OpenMausBot desktop and verify Accessibility + Screen Recording permissions.",
      );
    }
    const socketPath = extractSocketPath(connection.args);
    const callArgs = [
      "call",
      "screenshot",
      "{}",
      ...(socketPath ? ["--socket", socketPath] : []),
    ];
    const out = await context.runShell(connection.command, callArgs, {
      timeoutMs: 15_000,
      env: connection.env,
    });
    if (out.exitCode !== 0) {
      throw new AgentComputerError(
        "COMMAND_FAILED",
        `Local Cua screenshot failed: ${out.stderr.trim() || `exit ${out.exitCode}`}`,
        "Check Screen Recording permission for OpenMausBot in System Settings.",
      );
    }
    const raw = out.stdout.trim();
    let base64Data = raw;
    let mimeType: "image/png" | "image/jpeg" = "image/png";
    if (raw.startsWith("{")) {
      const parsed = JSON.parse(raw) as {
        data?: string;
        image?: string;
        base64?: string;
        mimeType?: string;
      };
      base64Data = parsed.data ?? parsed.image ?? parsed.base64 ?? "";
      if (parsed.mimeType === "image/jpeg") mimeType = "image/jpeg";
    }
    return {
      mimeType,
      base64Data,
      vncPreviewUrl: null,
      capturedAt: context.now(),
    };
  }

  async pauseOrStop(_lease: ComputerLease, _context: ProviderContext): Promise<LeaseLifecycleResult> {
    return {
      state: "stopped",
      detail: "Detached agent session from local embedded Cua AX host.",
    };
  }

  async destroyLease(_lease: ComputerLease, _context: ProviderContext): Promise<LeaseLifecycleResult> {
    return {
      state: "destroyed",
      detail: "Released local embedded Cua AX lease.",
    };
  }
}

server/agent-computers/providers/mac2-lu:
import {
  buildAgentComputerName,
  type ComputerLease,
  type ComputerLeaseRequest,
  type ComputerMcpEndpoint,
  type ComputerOsFamily,
  type Mac2HostConfig,
  type ProviderAvailability,
} from "../../../shared/agent-computers.ts";
import { AgentComputerError } from "../errors.ts";
import {
  buildCleanRemoteShellCommand,
  shellQuote,
  type ComputerProviderAdapter,
  type ExecCommandInput,
  type ExecCommandResult,
  type LeaseLifecycleResult,
  type ProviderContext,
  type ProvisionedComputer,
  type ScreenshotPreview,
} from "../types.ts";

interface LumeVmRecord {
  name?: string;
  status?: string;
  os?: string;
  ipAddress?: string | null;
  ip_address?: string | null;
  vncUrl?: string | null;
  vnc_url?: string | null;
}

interface LumeApiResponse {
  status: number;
  ok: boolean;
  body: unknown;
}

export interface Mac2LumeVmProviderOptions {
  readyPollDelaysMs?: readonly number[];
  guestUser?: string;
}

const DEFAULT_READY_POLL_DELAYS_MS = [0, 300, 700, 1_500, 2_500] as const;

function resolveMac2SshTarget(config: Mac2HostConfig): string | null {
  if (config.sshAlias) return config.sshAlias;
  if (config.tailscaleHost) {
    return config.sshUser ? `${config.sshUser}@${config.tailscaleHost}` : config.tailscaleHost;
  }
  return null;
}

function isRunningVm(vm: LumeVmRecord): boolean {
  const status = (vm.status ?? "").toLowerCase();
  return status === "running";
}

function vmOsFamily(vm: LumeVmRecord): ComputerOsFamily {
  const os = (vm.os ?? "").toLowerCase();
  return os.includes("linux") || os.includes("ubuntu") ? "linux" : "macos";
}

function extractGuestIp(vm: LumeVmRecord | null | undefined): string | null {
  const ip = vm?.ipAddress ?? vm?.ip_address ?? null;
  return typeof ip === "string" && ip.trim().length > 0 ? ip.trim() : null;
}

function rewriteTailscaleVncUrl(rawUrl: string | null | undefined, config: Mac2HostConfig): string | null {
  if (!rawUrl || typeof rawUrl !== "string") return null;
  if (!config.tailscaleHost) return rawUrl;
  return rawUrl.replace(/\/\/(127\.0\.0\.1|localhost)(?=[:/]|$)/i, `//${config.tailscaleHost}`);
}

export class Mac2LumeVmProvider implements ComputerProviderAdapter {
  readonly id = "mac2-lume-vm" as const;
  private readonly readyPollDelaysMs: readonly number[];
  private readonly guestUser: string;

  constructor(options: Mac2LumeVmProviderOptions = {}) {
    this.readyPollDelaysMs = options.readyPollDelaysMs ?? DEFAULT_READY_POLL_DELAYS_MS;
    this.guestUser = options.guestUser ?? "agent";
  }

  private async lumeRequest(
    context: ProviderContext,
    method: "GET" | "POST" | "PATCH" | "DELETE",
    path: string,
    payload?: Record<string, unknown>,
  ): Promise<LumeApiResponse> {
    const config = context.mac2Config;

    if (config.lumeTransport === "http" && config.tailscaleHost) {
      const url = `http://${config.tailscaleHost}:${config.lumePort}${path}`;
      const response = await context.fetchImpl(url, {
        method,
        headers: payload ? { "content-type": "application/json" } : undefined,
        body: payload ? JSON.stringify(payload) : undefined,
        signal: AbortSignal.timeout(30_000),
      });
      const text = await response.text();
      let body: unknown = null;
      if (text.trim()) {
        try {
          body = JSON.parse(text);
        } catch {
          body = text;
        }
      }
      return { status: response.status, ok: response.ok, body };
    }

    const sshTarget = resolveMac2SshTarget(config);
    if (!sshTarget) {
      throw new AgentComputerError(
        "MISSING_CREDENTIALS",
        "Mac #2 Lume host requires either tailscaleHost or sshAlias.",
        "Run ./scripts/setup-agent-mac.sh --install --init-vm-pool on Mac #2 and configure mac2.tailscaleHost.",
      );
    }

    const url = `http://127.0.0.1:${config.lumePort}${path}`;
    const bodyArg = payload ? `-H 'content-type: application/json' -d ${shellQuote(JSON.stringify(payload))}` : "";
    const remoteCurl = `curl -sS -w '\\n__HTTP_STATUS__:%{http_code}' -X ${method} ${bodyArg} ${shellQuote(url)}`;
    const out = await context.runShell(
      "ssh",
      ["-o", "BatchMode=yes", "-o", "ConnectTimeout=8", sshTarget, remoteCurl],
      { timeoutMs: 35_000 },
    );
    if (out.exitCode !== 0) {
      throw new Error(out.stderr.trim() || `SSH curl to Lume exited ${out.exitCode}`);
    }
    const markerIndex = out.stdout.lastIndexOf("\n__HTTP_STATUS__:");
    const rawBody = markerIndex >= 0 ? out.stdout.slice(0, markerIndex).trim() : out.stdout.trim();
    const statusText =
      markerIndex >= 0 ? out.stdout.slice(markerIndex + "\n__HTTP_STATUS__:".length).trim() : "200";
    const status = Number.parseInt(statusText, 10) || 500;
    let body: unknown = null;
    if (rawBody) {
      try {
        body = JSON.parse(rawBody);
      } catch {
        body = rawBody;
      }
    }
    return { status, ok: status >= 200 && status < 300, body };
  }

  private async listVms(context: ProviderContext): Promise<LumeVmRecord[]> {
    const res = await this.lumeRequest(context, "GET", "/lume/vms");
    if (!res.ok) {
      throw new Error(`Lume GET /lume/vms returned HTTP ${res.status}`);
    }
    if (Array.isArray(res.body)) {
      return res.body as LumeVmRecord[];
    }
    if (res.body && typeof res.body === "object" && Array.isArray((res.body as { vms?: unknown }).vms)) {
      return (res.body as { vms: LumeVmRecord[] }).vms;
    }
    return [];
  }

  private async inspectVm(context: ProviderContext, vmName: string): Promise<LumeVmRecord | null> {
    const res = await this.lumeRequest(
      context,
      "GET",
      `/lume/vms/${encodeURIComponent(vmName)}`,
    );
    if (res.status === 404) return null;
    if (!res.ok || !res.body || typeof res.body !== "object") return null;
    return res.body as LumeVmRecord;
  }

  private async cloneVm(
    context: ProviderContext,
    sourceName: string,
    newName: string,
  ): Promise<void> {
    // Support both `POST /lume/vms/clone` ({ name, newName }) and `POST /lume/vms/{name}/clone` ({ newName }).
    const primary = await this.lumeRequest(context, "POST", "/lume/vms/clone", {
      name: sourceName,
      newName,
    });
    if (primary.ok) return;
    if (primary.status === 404 || primary.status === 405) {
      const alt = await this.lumeRequest(
        context,
        "POST",
        `/lume/vms/${encodeURIComponent(sourceName)}/clone`,
        { newName },
      );
      if (alt.ok) return;
      throw new AgentComputerError(
        "PROVIDER_ERROR",
        `Lume failed to clone base VM '${sourceName}' to '${newName}' (HTTP ${alt.status}).`,
        `Run ./scripts/setup-agent-mac.sh --init-vm-pool on Mac #2 to ensure '${sourceName}' exists.`,
        502,
      );
    }
    throw new AgentComputerError(
      "PROVIDER_ERROR",
      `Lume failed to clone base VM '${sourceName}' to '${newName}' (HTTP ${primary.status}).`,
      `Verify base template '${sourceName}' exists in 'lume ls' on Mac #2.`,
      502,
    );
  }

  async checkAvailability(context: ProviderContext): Promise<ProviderAvailability> {
    const config = context.mac2Config;
    const trackedActive = context.activeLeases.filter(
      (lease) => lease.provider === this.id && lease.state === "running",
    ).length;

    if (!config.enabled) {
      return {
        provider: this.id,
        available: false,
        state: "disabled",
        reasonCode: "disabled",
        message: "Mac #2 Lume VM pool is disabled.",
        nextStep: "Enable mac2.enabled in agent-computers.json.",
        activeLeases: trackedActive,
        maxCapacity: config.maxConcurrentVms,
        supportedOs: ["macos", "linux"],
        checkedAt: context.now(),
      };
    }

    const hasEndpoint =
      (config.lumeTransport === "http" && Boolean(config.tailscaleHost)) ||
      Boolean(resolveMac2SshTarget(config));

    if (!hasEndpoint) {
      return {
        provider: this.id,
        available: false,
        state: "missing_credentials",
        reasonCode: "missing_credentials",
        message: "Mac #2 Lume hypervisor host is not configured yet.",
        nextStep:
          "Run ./scripts/setup-agent-mac.sh --install --init-vm-pool on your reset 2nd Mac and set mac2.tailscaleHost.",
        activeLeases: trackedActive,
        maxCapacity: config.maxConcurrentVms,
        supportedOs: ["macos", "linux"],
        checkedAt: context.now(),
      };
    }

    let vms: LumeVmRecord[];
    try {
      vms = await this.listVms(context);
    } catch (error) {
      return {
        provider: this.id,
        available: false,
        state: "host_offline",
        reasonCode: "host_offline",
        message: `Could not reach Lume daemon on ${config.name}: ${
          error instanceof Error ? error.message : String(error)
        }`,
        nextStep:
          "Confirm Tailscale is online and LaunchAgent com.xlabs.agent-mac-host (lume serve on 127.0.0.1:7777) is active on Mac #2.",
        activeLeases: trackedActive,
        maxCapacity: config.maxConcurrentVms,
        supportedOs: ["macos", "linux"],
        checkedAt: context.now(),
      };
    }

    const runningCount = Math.max(trackedActive, vms.filter(isRunningVm).length);
    if (runningCount >= config.maxConcurrentVms) {
      return {
        provider: this.id,
        available: false,
        state: "capacity_full",
        reasonCode: "capacity_full",
        message: `${config.name} Lume VM pool is full (${runningCount}/${config.maxConcurrentVms} VMs running).`,
        nextStep: "Stop an idle VM or allow Cloud Burst fallback to Cua Cloud / Daytona.",
        activeLeases: runningCount,
        maxCapacity: config.maxConcurrentVms,
        supportedOs: ["macos", "linux"],
        checkedAt: context.now(),
      };
    }

    const hasMacBase = vms.some((vm) => vm.name === config.macosBaseImage);
    const hasLinuxBase = vms.some((vm) => vm.name === config.linuxBaseImage);
    const supportedOs: ComputerOsFamily[] = [];
    if (hasMacBase || (!hasMacBase && !hasLinuxBase)) supportedOs.push("macos");
    if (hasLinuxBase || (!hasMacBase && !hasLinuxBase)) supportedOs.push("linux");

    return {
      provider: this.id,
      available: true,
      state: "ready",
      reasonCode: "ok",
      message: `${config.name} Lume hypervisor ready (${runningCount}/${config.maxConcurrentVms} VM slots active).`,
      nextStep: null,
      activeLeases: runningCount,
      maxCapacity: config.maxConcurrentVms,
      supportedOs,
      checkedAt: context.now(),
    };
  }

  async provisionOrLease(
    request: ComputerLeaseRequest,
    context: ProviderContext,
  ): Promise<ProvisionedComputer> {
    if (request.os === "windows") {
      throw new AgentComputerError(
        "UNSUPPORTED_OS",
        "Apple Virtualization.framework (Lume) supports macOS and Linux guests only, not Windows.",
        "Route Windows computer-use sessions to cua-cloud.",
        400,
      );
    }

    const config = context.mac2Config;
    const vmName = buildAgentComputerName(request);
    const baseImage = request.os === "linux" ? config.linuxBaseImage : config.macosBaseImage;

    let vms: LumeVmRecord[];
    try {
      vms = await this.listVms(context);
    } catch (error) {
      throw new AgentComputerError(
        "HOST_OFFLINE",
        `Could not reach Lume on ${config.name}: ${error instanceof Error ? error.message : String(error)}`,
        "Verify Tailscale and com.xlabs.agent-mac-host on Mac #2, or enable Cloud Burst.",
        503,
      );
    }

    const existingVm = vms.find((vm) => vm.name === vmName);
    const otherRunningVms = vms.filter((vm) => vm.name !== vmName && isRunningVm(vm));
    const trackedOtherRunning = context.activeLeases.filter(
      (lease) =>
        lease.provider === this.id &&
        lease.state === "running" &&
        lease.instanceId !== vmName,
    );

    const effectiveRunningCount = Math.max(otherRunningVms.length, trackedOtherRunning.length);
    if (effectiveRunningCount >= config.maxConcurrentVms) {
      throw new AgentComputerError(
        "CAPACITY_FULL",
        `${config.name} is already running ${effectiveRunningCount}/${config.maxConcurrentVms} VMs.`,
        "Stop an idle VM or allow Cloud Burst fallback.",
      );
    }

    if (request.os === "macos") {
      const runningMacVms = Math.max(
        otherRunningVms.filter((vm) => vmOsFamily(vm) === "macos").length,
        trackedOtherRunning.filter((lease) => lease.os === "macos").length,
      );
      if (runningMacVms >= config.maxMacOsVms) {
        throw new AgentComputerError(
          "CAPACITY_FULL",
          `${config.name} already runs ${runningMacVms}/${config.maxMacOsVms} macOS VMs (Apple Virtualization.framework limit).`,
          "Use os='linux' on mac2-lume-vm or allow Cloud Burst to cua-cloud for additional macOS desktops.",
        );
      }
    }

    if (request.mode === "temporary") {
      if (existingVm) {
        await this.lumeRequest(
          context,
          "POST",
          `/lume/vms/${encodeURIComponent(vmName)}/stop`,
          {},
        ).catch(() => null);
        await this.lumeRequest(
          context,
          "DELETE",
          `/lume/vms/${encodeURIComponent(vmName)}`,
        ).catch(() => null);
      }
      await this.cloneVm(context, baseImage, vmName);
    } else if (!existingVm) {
      await this.cloneVm(context, baseImage, vmName);
    }

    if (request.cpuCores !== undefined || request.memoryGb !== undefined) {
      const sizing: Record<string, unknown> = {};
      if (request.cpuCores !== undefined) sizing.cpu = request.cpuCores;
      if (request.memoryGb !== undefined) sizing.memory = `${request.memoryGb}GB`;
      await this.lumeRequest(
        context,
        "PATCH",
        `/lume/vms/${encodeURIComponent(vmName)}`,
        sizing,
      ).catch(() => null);
    }

    if (!existingVm || !isRunningVm(existingVm)) {
      const started = await this.lumeRequest(
        context,
        "POST",
        `/lume/vms/${encodeURIComponent(vmName)}/run`,
        { noDisplay: true },
      );
      if (!started.ok && started.status !== 409) {
        throw new AgentComputerError(
          "PROVIDER_ERROR",
          `Lume failed to start VM '${vmName}' (HTTP ${started.status}).`,
          `Inspect 'lume get ${vmName}' on Mac #2.`,
          502,
        );
      }
    }

    let detail: LumeVmRecord | null = null;
    for (const delayMs of this.readyPollDelaysMs) {
      if (delayMs > 0) {
        await new Promise((resolve) => setTimeout(resolve, delayMs));
      }
      detail = await this.inspectVm(context, vmName);
      if (detail && isRunningVm(detail) && extractGuestIp(detail)) {
        break;
      }
    }

    const guestIp = extractGuestIp(detail);
    const vncPreviewUrl = rewriteTailscaleVncUrl(
      detail?.vncUrl ?? detail?.vnc_url ?? null,
      config,
    );

    return {
      instanceId: vmName,
      instanceName: vmName,
      os: request.os,
      state: "running",
      guestIp,
      vncPreviewUrl,
      snapshotName: null,
    };
  }

  private buildGuestSshArgs(lease: ComputerLease, config: Mac2HostConfig, remoteCommand: string): string[] {
    if (!lease.guestIp) {
      throw new AgentComputerError(
        "PROVIDER_ERROR",
        `Lume VM '${lease.instanceId}' has no guest IP address yet.`,
        `Verify '${lease.instanceId}' finished booting via 'lume get ${lease.instanceId}'.`,
      );
    }
    const jumpHost = resolveMac2SshTarget(config);
    const guestTarget = `${this.guestUser}@${lease.guestIp}`;
    return [
      "-o",
      "BatchMode=yes",
      "-o",
      "StrictHostKeyChecking=accept-new",
      "-o",
      "ConnectTimeout=10",
      ...(jumpHost ? ["-J", jumpHost] : []),
      guestTarget,
      remoteCommand,
    ];
  }

  async execCommand(
    lease: ComputerLease,
    input: ExecCommandInput,
    context: ProviderContext,
  ): Promise<ExecCommandResult> {
    const startedAt = context.now();
    const sshArgs = this.buildGuestSshArgs(
      lease,
      context.mac2Config,
      buildCleanRemoteShellCommand(input.command, input.cwd),
    );
    const out = await context.runShell("ssh", sshArgs, {
      timeoutMs: input.timeoutMs ?? 60_000,
    });
    return {
      ok: out.exitCode === 0,
      exitCode: out.exitCode,
      stdout: out.stdout,
      stderr: out.stderr,
      durationMs: Math.max(0, context.now() - startedAt),
    };
  }

  async mcpEndpoint(lease: ComputerLease, context: ProviderContext): Promise<ComputerMcpEndpoint | null> {
    if (!lease.guestIp) return null;
    const jumpHost = resolveMac2SshTarget(context.mac2Config);
    return {
      kind: "stdio",
      toolSurface: "cua-driver",
      command: "ssh",
      args: [
        "-o",
        "BatchMode=yes",
        "-o",
        "StrictHostKeyChecking=accept-new",
        ...(jumpHost ? ["-J", jumpHost] : []),
        `${this.guestUser}@${lease.guestIp}`,
        "cua-driver",
        "mcp",
      ],
      env: {
        XLABS_LUME_VM: lease.instanceId,
      },
    };
  }

  async screenshotPreview(
    lease: ComputerLease,
    context: ProviderContext,
  ): Promise<ScreenshotPreview> {
    const sshArgs = this.buildGuestSshArgs(
      lease,
      context.mac2Config,
      "cua-driver call screenshot '{}'",
    );
    const out = await context.runShell("ssh", sshArgs, { timeoutMs: 15_000 });
    if (out.exitCode !== 0) {
      throw new AgentComputerError(
        "COMMAND_FAILED",
        `Lume VM '${lease.instanceId}' screenshot failed: ${out.stderr.trim() || `exit ${out.exitCode}`}`,
        "Verify cua-driver is running inside the guest VM template.",
      );
    }
    const raw = out.stdout.trim();
    let base64Data = raw;
    if (raw.startsWith("{")) {
      const parsed = JSON.parse(raw) as { data?: string; image?: string; base64?: string };
      base64Data = parsed.data ?? parsed.image ?? parsed.base64 ?? "";
    }
    return {
      mimeType: "image/png",
      base64Data,
      vncPreviewUrl: lease.vncPreviewUrl,
      capturedAt: context.now(),
    };
  }

  async pauseOrStop(
    lease: ComputerLease,
    context: ProviderContext,
  ): Promise<LeaseLifecycleResult> {
    const vmName = lease.instanceId;
    const stopped = await this.lumeRequest(
      context,
      "POST",
      `/lume/vms/${encodeURIComponent(vmName)}/stop`,
      {},
    );
    if (!stopped.ok && stopped.status !== 404 && stopped.status !== 409) {
      throw new AgentComputerError(
        "PROVIDER_ERROR",
        `Failed to stop Lume VM '${vmName}' (HTTP ${stopped.status}).`,
        `Inspect 'lume get ${vmName}' on Mac #2.`,
        502,
      );
    }

    let snapshotName: string | null = lease.snapshotName;
    if (lease.mode === "long-term" && context.mac2Config.snapshotOnLongTermStop) {
      const candidateSnap = `${vmName}-snap`;
      await this.lumeRequest(
        context,
        "DELETE",
        `/lume/vms/${encodeURIComponent(candidateSnap)}`,
      ).catch(() => null);
      const snapped = await this.lumeRequest(context, "POST", "/lume/vms/clone", {
        name: vmName,
        newName: candidateSnap,
      }).catch(() => ({ ok: false, status: 500, body: null }));
      if (snapped.ok) {
        snapshotName = candidateSnap;
      }
    }

    return {
      state: "stopped",
      snapshotName,
      detail: `Stopped persistent Lume VM '${vmName}' cleanly.`,
    };
  }

  async destroyLease(
    lease: ComputerLease,
    context: ProviderContext,
  ): Promise<LeaseLifecycleResult> {
    const vmName = lease.instanceId;
    await this.lumeRequest(
      context,
      "POST",
      `/lume/vms/${encodeURIComponent(vmName)}/stop`,
      {},
    ).catch(() => null);

    const deleted = await this.lumeRequest(
      context,
      "DELETE",
      `/lume/vms/${encodeURIComponent(vmName)}`,
    );
    if (!deleted.ok && deleted.status !== 404 && deleted.status !== 410) {
      throw new AgentComputerError(
        "PROVIDER_ERROR",
        `Failed to delete Lume VM '${vmName}' (HTTP ${deleted.status}).`,
        `Run 'lume delete ${vmName} --force' on Mac #2 to reclaim disk.`,
        502,
      );
    }
    return {
      state: "destroyed",
      snapshotName: null,
      detail: `Destroyed and wiped Lume VM '${vmName}'.`,
    };
  }
}

server/agent-computers/providers/mac2-sh:
import type {
  ComputerLease,
  ComputerLeaseRequest,
  ComputerMcpEndpoint,
  Mac2HostConfig,
  ProviderAvailability,
} from "../../../shared/agent-computers.ts";
import type { SharedComputers } from "../../shared-computers.ts";
import { AgentComputerError } from "../errors.ts";
import {
  buildCleanRemoteShellCommand,
  type ComputerProviderAdapter,
  type ExecCommandInput,
  type ExecCommandResult,
  type LeaseLifecycleResult,
  type ProviderContext,
  type ProvisionedComputer,
  type ScreenshotPreview,
} from "../types.ts";

export interface Mac2SharedProviderOptions {
  sharedComputers?: SharedComputers;
}

const REMOTE_CUA_DRIVER_RESOLVER =
  'for b in /usr/local/bin/cua-driver "$HOME/.local/bin/cua-driver" /Applications/CuaDriver.app/Contents/MacOS/cua-driver; do if [ -x "$b" ]; then CUA_BIN="$b"; break; fi; done; if [ -z "${CUA_BIN:-}" ]; then echo "cua-driver not found on Mac #2" >&2; exit 127; fi';

function resolveSshTarget(config: Mac2HostConfig): string | null {
  if (config.sshAlias) return config.sshAlias;
  if (config.tailscaleHost) {
    return config.sshUser ? `${config.sshUser}@${config.tailscaleHost}` : config.tailscaleHost;
  }
  return null;
}

export class Mac2SharedProvider implements ComputerProviderAdapter {
  readonly id = "mac2-shared" as const;
  private readonly sharedComputers: SharedComputers | undefined;

  constructor(options: Mac2SharedProviderOptions = {}) {
    this.sharedComputers = options.sharedComputers;
  }

  async checkAvailability(context: ProviderContext): Promise<ProviderAvailability> {
    const config = context.mac2Config;
    const activeLeases = context.activeLeases.filter(
      (lease) => lease.provider === this.id && lease.state === "running",
    ).length;

    if (!config.enabled) {
      return {
        provider: this.id,
        available: false,
        state: "disabled",
        reasonCode: "disabled",
        message: "Secondary Mac host is disabled in configuration.",
        nextStep: "Enable mac2.enabled in agent-computers.json.",
        activeLeases,
        maxCapacity: 1,
        supportedOs: ["macos"],
        checkedAt: context.now(),
      };
    }

    const hasSharedBinding = Boolean(
      this.sharedComputers && config.sharedComputerId && config.sharedOwnerPerson,
    );
    const sshTarget = resolveSshTarget(config);

    if (!hasSharedBinding && !sshTarget) {
      return {
        provider: this.id,
        available: false,
        state: "missing_credentials",
        reasonCode: "missing_credentials",
        message: "Secondary Mac direct host has no paired SharedComputers ID or Tailscale SSH host.",
        nextStep:
          "Run ./scripts/setup-agent-mac.sh --install --pair-url <url> on the 2nd Mac or set mac2.tailscaleHost.",
        activeLeases,
        maxCapacity: 1,
        supportedOs: ["macos"],
        checkedAt: context.now(),
      };
    }

    if (hasSharedBinding && this.sharedComputers && config.sharedOwnerPerson && config.sharedComputerId) {
      const entry = this.sharedComputers
        .status(config.sharedOwnerPerson)
        .find((item) => item.id === config.sharedComputerId);

      if (entry?.online) {
        if (entry.busy || activeLeases >= 1) {
          return {
            provider: this.id,
            available: false,
            state: "capacity_full",
            reasonCode: "capacity_full",
            message: `${entry.name} is busy on its single bare-metal cursor.`,
            nextStep: "Use mac2-lume-vm to run 2–4 isolated agents concurrently on Mac #2.",
            activeLeases: Math.max(activeLeases, 1),
            maxCapacity: 1,
            supportedOs: ["macos"],
            checkedAt: context.now(),
          };
        }
        return {
          provider: this.id,
          available: true,
          state: "ready",
          reasonCode: "ok",
          message: `${entry.name} is paired and online via OpenMausBot SharedComputers.`,
          nextStep: null,
          activeLeases,
          maxCapacity: 1,
          supportedOs: ["macos"],
          checkedAt: context.now(),
        };
      }
    }

    if (sshTarget) {
      try {
        const probe = await context.runShell(
          "ssh",
          ["-o", "BatchMode=yes", "-o", "ConnectTimeout=5", sshTarget, "uname -s"],
          { timeoutMs: 7_000 },
        );
        if (probe.exitCode === 0 && probe.stdout.trim() === "Darwin") {
          if (activeLeases >= 1) {
            return {
              provider: this.id,
              available: false,
              state: "capacity_full",
              reasonCode: "capacity_full",
              message: `${config.name} direct screen is already leased by an active agent.`,
              nextStep: "Use mac2-lume-vm for concurrent isolated VMs on the same 2nd Mac.",
              activeLeases,
              maxCapacity: 1,
              supportedOs: ["macos"],
              checkedAt: context.now(),
            };
          }
          return {
            provider: this.id,
            available: true,
            state: "ready",
            reasonCode: "ok",
            message: `${config.name} is online over Tailscale SSH (${sshTarget}).`,
            nextStep: null,
            activeLeases,
            maxCapacity: 1,
            supportedOs: ["macos"],
            checkedAt: context.now(),
          };
        }
      } catch {
        // Handled below as host_offline.
      }
    }

    return {
      provider: this.id,
      available: false,
      state: "host_offline",
      reasonCode: "host_offline",
      message: `${config.name} is offline or unreachable over SharedComputers / Tailscale.`,
      nextStep:
        "Ensure the 2nd Mac is powered on AC, connected to Tailscale, and running LaunchAgent com.xlabs.agent-mac-host.",
      activeLeases,
      maxCapacity: 1,
      supportedOs: ["macos"],
      checkedAt: context.now(),
    };
  }

  async provisionOrLease(
    request: ComputerLeaseRequest,
    context: ProviderContext,
  ): Promise<ProvisionedComputer> {
    if (request.os !== "macos") {
      throw new AgentComputerError(
        "UNSUPPORTED_OS",
        `mac2-shared runs bare-metal macOS, cannot satisfy OS ${request.os}.`,
        "Use mac2-lume-vm with os='linux' for Ubuntu on Mac #2, or cua-cloud for Windows.",
        400,
      );
    }
    const availability = await this.checkAvailability(context);
    if (!availability.available) {
      throw new AgentComputerError(
        availability.state === "capacity_full"
          ? "CAPACITY_FULL"
          : availability.state === "missing_credentials"
            ? "MISSING_CREDENTIALS"
            : "HOST_OFFLINE",
        availability.message,
        availability.nextStep ?? "Configure Mac #2 host connection.",
      );
    }
    const config = context.mac2Config;
    return {
      instanceId: config.sharedComputerId ?? resolveSshTarget(config) ?? "mac2-host",
      instanceName: config.name,
      os: "macos",
      state: "running",
      guestIp: config.tailscaleHost ?? null,
      vncPreviewUrl: config.tailscaleHost ? `vnc://${config.tailscaleHost}:5900` : null,
    };
  }

  async execCommand(
    _lease: ComputerLease,
    input: ExecCommandInput,
    context: ProviderContext,
  ): Promise<ExecCommandResult> {
    const startedAt = context.now();
    const config = context.mac2Config;

    if (this.sharedComputers && config.sharedComputerId && config.sharedOwnerPerson) {
      const status = this.sharedComputers
        .status(config.sharedOwnerPerson)
        .find((item) => item.id === config.sharedComputerId);
      if (status?.online && status.scopes.terminal) {
        const timeoutSeconds = Math.min(
          240,
          Math.max(1, Math.ceil((input.timeoutMs ?? 60_000) / 1000)),
        );
        const raw = (await this.sharedComputers.request(
          {
            computer_id: config.sharedComputerId,
            action: "run_command",
            command: input.cwd
              ? `cd '${input.cwd.replace(/'/g, "'\\''")}' && ${input.command}`
              : input.command,
            timeout_seconds: timeoutSeconds,
          },
          config.sharedOwnerPerson,
          () => true,
        )) as { exitCode?: number; stdout?: string; stderr?: string } | null;

        const exitCode = typeof raw?.exitCode === "number" ? raw.exitCode : 0;
        return {
          ok: exitCode === 0,
          exitCode,
          stdout: typeof raw?.stdout === "string" ? raw.stdout : "",
          stderr: typeof raw?.stderr === "string" ? raw.stderr : "",
          durationMs: Math.max(0, context.now() - startedAt),
        };
      }
    }

    const sshTarget = resolveSshTarget(config);
    if (!sshTarget) {
      throw new AgentComputerError(
        "HOST_OFFLINE",
        "No online SharedComputers terminal or SSH target available for Mac #2.",
        "Verify Tailscale SSH or OpenMausBot pairing on Mac #2.",
      );
    }

    const out = await context.runShell(
      "ssh",
      [
        "-o",
        "BatchMode=yes",
        "-o",
        "ConnectTimeout=10",
        sshTarget,
        buildCleanRemoteShellCommand(input.command, input.cwd),
      ],
      { timeoutMs: input.timeoutMs ?? 60_000 },
    );
    return {
      ok: out.exitCode === 0,
      exitCode: out.exitCode,
      stdout: out.stdout,
      stderr: out.stderr,
      durationMs: Math.max(0, context.now() - startedAt),
    };
  }

  async mcpEndpoint(_lease: ComputerLease, context: ProviderContext): Promise<ComputerMcpEndpoint | null> {
    const config = context.mac2Config;
    const sshTarget = resolveSshTarget(config);
    if (sshTarget) {
      return {
        kind: "stdio",
        toolSurface: "cua-driver",
        command: "ssh",
        args: [
          "-o",
          "BatchMode=yes",
          sshTarget,
          `${REMOTE_CUA_DRIVER_RESOLVER}; exec "$CUA_BIN" mcp`,
        ],
      };
    }
    if (config.sharedComputerId) {
      return {
        kind: "rest-bridge",
        toolSurface: "shared-computer",
        env: { OMB_SHARED_COMPUTER_ID: config.sharedComputerId },
      };
    }
    return null;
  }

  async screenshotPreview(
    _lease: ComputerLease,
    context: ProviderContext,
  ): Promise<ScreenshotPreview> {
    const config = context.mac2Config;
    if (this.sharedComputers && config.sharedComputerId && config.sharedOwnerPerson) {
      const status = this.sharedComputers
        .status(config.sharedOwnerPerson)
        .find((item) => item.id === config.sharedComputerId);
      if (status?.online && status.scopes.screen) {
        const result = (await this.sharedComputers.request(
          {
            computer_id: config.sharedComputerId,
            action: "computer_call",
            tool_name: "screenshot",
            arguments: {},
          },
          config.sharedOwnerPerson,
          () => true,
        )) as { data?: string; image?: string } | null;
        return {
          mimeType: "image/png",
          base64Data: result?.data ?? result?.image ?? "",
          vncPreviewUrl: config.tailscaleHost ? `vnc://${config.tailscaleHost}:5900` : null,
          capturedAt: context.now(),
        };
      }
    }

    const sshTarget = resolveSshTarget(config);
    if (!sshTarget) {
      throw new AgentComputerError(
        "HOST_OFFLINE",
        "Cannot capture screenshot on Mac #2: neither screen lending nor SSH is reachable.",
        "Open OpenMausBot on Mac #2 or enable Tailscale SSH.",
      );
    }
    const out = await context.runShell(
      "ssh",
      [
        "-o",
        "BatchMode=yes",
        sshTarget,
        `${REMOTE_CUA_DRIVER_RESOLVER}; exec "$CUA_BIN" call get_desktop_state '{}'`,
      ],
      { timeoutMs: 15_000 },
    );
    if (out.exitCode !== 0) {
      throw new AgentComputerError(
        "COMMAND_FAILED",
        `Mac #2 screenshot failed: ${out.stderr.trim() || `exit ${out.exitCode}`}`,
        "Verify Screen Recording permission for cua-driver on Mac #2.",
      );
    }
    return {
      mimeType: "image/png",
      base64Data: out.stdout.trim(),
      vncPreviewUrl: config.tailscaleHost ? `vnc://${config.tailscaleHost}:5900` : null,
      capturedAt: context.now(),
    };
  }

  async pauseOrStop(_lease: ComputerLease, _context: ProviderContext): Promise<LeaseLifecycleResult> {
    return {
      state: "stopped",
      detail: "Released direct host lease on Mac #2 (host remains online).",
    };
  }

  async destroyLease(_lease: ComputerLease, _context: ProviderContext): Promise<LeaseLifecycleResult> {
    return {
      state: "destroyed",
      detail: "Released direct host lease on Mac #2.",
    };
  }
}

server/agent-computers/providers/orgo.ts:
import {
  buildAgentComputerName,
  type ComputerLease,
  type ComputerLeaseRequest,
  type ComputerMcpEndpoint,
  type ProviderAvailability,
} from "../../../shared/agent-computers.ts";
import { AgentComputerError } from "../errors.ts";
import type {
  ComputerProviderAdapter,
  ExecCommandInput,
  ExecCommandResult,
  LeaseLifecycleResult,
  ProviderContext,
  ProvisionedComputer,
  ScreenshotPreview,
} from "../types.ts";

interface OrgoComputerRecord {
  id?: string;
  name?: string;
  status?: string;
  state?: string;
  url?: string | null;
  vnc_url?: string | null;
}

export interface OrgoProviderOptions {
  maxCapacity?: number;
}

export class OrgoProvider implements ComputerProviderAdapter {
  readonly id = "orgo" as const;
  private readonly maxCapacity: number;

  constructor(options: OrgoProviderOptions = {}) {
    this.maxCapacity = options.maxCapacity ?? 50;
  }

  private requireApiKey(context: ProviderContext): string {
    const key = context.settings.orgoApiKey;
    if (!key) {
      throw new AgentComputerError(
        "MISSING_CREDENTIALS",
        "ORGO_API_KEY is missing from runtime environment.",
        "Inject ORGO_API_KEY via Bitwarden Secrets Manager: keys run stable -- pnpm dev:server",
      );
    }
    return key;
  }

  private async apiRequest(
    context: ProviderContext,
    method: "GET" | "POST" | "DELETE",
    path: string,
    payload?: Record<string, unknown>,
  ): Promise<{ ok: boolean; status: number; contentType: string; bytes: Uint8Array; body: unknown }> {
    const key = this.requireApiKey(context);
    const response = await context.fetchImpl(`${context.settings.orgoApiBaseUrl}${path}`, {
      method,
      headers: {
        authorization: `Bearer ${key}`,
        ...(payload ? { "content-type": "application/json" } : {}),
      },
      body: payload ? JSON.stringify(payload) : undefined,
      signal: AbortSignal.timeout(30_000),
    });
    const contentType = (response.headers.get("content-type") ?? "").toLowerCase();
    const bytes = new Uint8Array(await response.arrayBuffer());
    let body: unknown = null;
    if (!contentType.startsWith("image/") && bytes.byteLength > 0) {
      const text = Buffer.from(bytes).toString("utf8");
      try {
        body = JSON.parse(text);
      } catch {
        body = text;
      }
    }
    return { ok: response.ok, status: response.status, contentType, bytes, body };
  }

  async checkAvailability(context: ProviderContext): Promise<ProviderAvailability> {
    const activeLeases = context.activeLeases.filter(
      (lease) => lease.provider === this.id && lease.state === "running",
    ).length;

    if (!context.settings.orgoApiKey) {
      return {
        provider: this.id,
        available: false,
        state: "missing_credentials",
        reasonCode: "missing_api_key",
        message: "ORGO_API_KEY is not set in environment.",
        nextStep: "Inject ORGO_API_KEY at runtime via: keys run stable -- pnpm dev:server",
        activeLeases,
        maxCapacity: this.maxCapacity,
        supportedOs: ["linux"],
        checkedAt: context.now(),
      };
    }

    try {
      const res = await this.apiRequest(context, "GET", "/computers");
      if (res.status === 401 || res.status === 403) {
        return {
          provider: this.id,
          available: false,
          state: "missing_credentials",
          reasonCode: "auth_rejected",
          message: "Orgo.ai rejected ORGO_API_KEY (HTTP 401/403).",
          nextStep: "Verify or rotate ORGO_API_KEY in Bitwarden Secrets Manager.",
          activeLeases,
          maxCapacity: this.maxCapacity,
          supportedOs: ["linux"],
          checkedAt: context.now(),
        };
      }
      if (!res.ok) {
        return {
          provider: this.id,
          available: false,
          state: "degraded",
          reasonCode: "provider_error",
          message: `Orgo.ai status check returned HTTP ${res.status}.`,
          nextStep: "Check https://www.orgo.ai status.",
          activeLeases,
          maxCapacity: this.maxCapacity,
          supportedOs: ["linux"],
          checkedAt: context.now(),
        };
      }
      return {
        provider: this.id,
        available: activeLeases < this.maxCapacity,
        state: activeLeases < this.maxCapacity ? "ready" : "capacity_full",
        reasonCode: activeLeases < this.maxCapacity ? "ok" : "capacity_full",
        message: "Orgo.ai Ubuntu computer-use VMs ready (/computers API).",
        nextStep: null,
        activeLeases,
        maxCapacity: this.maxCapacity,
        supportedOs: ["linux"],
        checkedAt: context.now(),
      };
    } catch (error) {
      return {
        provider: this.id,
        available: false,
        state: "host_offline",
        reasonCode: "host_offline",
        message: `Could not reach Orgo.ai API: ${error instanceof Error ? error.message : String(error)}`,
        nextStep: "Check network connectivity to www.orgo.ai.",
        activeLeases,
        maxCapacity: this.maxCapacity,
        supportedOs: ["linux"],
        checkedAt: context.now(),
      };
    }
  }

  private extractComputers(raw: unknown): OrgoComputerRecord[] {
    if (Array.isArray(raw)) return raw as OrgoComputerRecord[];
    if (raw && typeof raw === "object" && Array.isArray((raw as { computers?: unknown }).computers)) {
      return (raw as { computers: OrgoComputerRecord[] }).computers;
    }
    return [];
  }

  async provisionOrLease(
    request: ComputerLeaseRequest,
    context: ProviderContext,
  ): Promise<ProvisionedComputer> {
    if (request.os !== "linux") {
      throw new AgentComputerError(
        "UNSUPPORTED_OS",
        `Orgo.ai provides Ubuntu Linux desktops only, cannot satisfy OS '${request.os}'.`,
        "Use mac2-lume-vm or cua-cloud for macOS/Windows.",
        400,
      );
    }

    this.requireApiKey(context);
    const computerName = buildAgentComputerName(request);

    if (request.mode === "long-term") {
      const listed = await this.apiRequest(context, "GET", "/computers");
      if (listed.ok) {
        const existing = this.extractComputers(listed.body).find(
          (item) => item.name === computerName && typeof item.id === "string",
        );
        if (existing && existing.id) {
          const state = (existing.status ?? existing.state ?? "").toLowerCase();
          if (state !== "running") {
            const started = await this.apiRequest(
              context,
              "POST",
              `/computers/${encodeURIComponent(existing.id)}/start`,
              {},
            );
            if (!started.ok && started.status !== 409) {
              throw new AgentComputerError(
                "PROVIDER_ERROR",
                `Failed to start Orgo computer '${computerName}' (HTTP ${started.status}).`,
                "Check Orgo workspace quota.",
                502,
              );
            }
          }
          return {
            instanceId: existing.id,
            instanceName: computerName,
            os: "linux",
            state: "running",
            vncPreviewUrl: existing.vnc_url ?? existing.url ?? null,
          };
        }
      }
    }

    const created = await this.apiRequest(context, "POST", "/computers", {
      name: computerName,
      cpu: request.cpuCores ?? 2,
      ram: request.memoryGb ?? 4,
    });
    if (!created.ok || !created.body || typeof created.body !== "object") {
      throw new AgentComputerError(
        created.status === 401 || created.status === 403 ? "MISSING_CREDENTIALS" : "PROVIDER_ERROR",
        `Orgo.ai failed to create computer '${computerName}' (HTTP ${created.status}).`,
        "Check ORGO_API_KEY and project quota.",
        created.status >= 400 && created.status < 600 ? created.status : 502,
      );
    }

    const record = ((created.body as { computer?: OrgoComputerRecord }).computer ??
      created.body) as OrgoComputerRecord;
    return {
      instanceId: record.id ?? computerName,
      instanceName: record.name ?? computerName,
      os: "linux",
      state: "running",
      vncPreviewUrl: record.vnc_url ?? record.url ?? null,
    };
  }

  async execCommand(
    lease: ComputerLease,
    input: ExecCommandInput,
    context: ProviderContext,
  ): Promise<ExecCommandResult> {
    const startedAt = context.now();
    const command = input.cwd
      ? `cd '${input.cwd.replace(/'/g, "'\\''")}' && ${input.command}`
      : input.command;
    const res = await this.apiRequest(
      context,
      "POST",
      `/computers/${encodeURIComponent(lease.instanceId)}/bash`,
      { command },
    );
    if (!res.ok) {
      throw new AgentComputerError(
        "COMMAND_FAILED",
        `Orgo /bash failed on '${lease.instanceId}' (HTTP ${res.status}).`,
        "Verify the Orgo computer is running.",
      );
    }
    const payload = (res.body && typeof res.body === "object" ? res.body : {}) as {
      exit_code?: number;
      exitCode?: number;
      output?: string;
      stdout?: string;
      stderr?: string;
    };
    const exitCode = payload.exitCode ?? payload.exit_code ?? 0;
    return {
      ok: exitCode === 0,
      exitCode,
      stdout: payload.stdout ?? payload.output ?? "",
      stderr: payload.stderr ?? "",
      durationMs: Math.max(0, context.now() - startedAt),
    };
  }

  /** Direct Orgo GUI mouse click action (`POST /computers/{id}/click`). */
  async click(
    lease: ComputerLease,
    point: { x: number; y: number; button?: "left" | "right" | "middle" },
    context: ProviderContext,
  ): Promise<void> {
    const res = await this.apiRequest(
      context,
      "POST",
      `/computers/${encodeURIComponent(lease.instanceId)}/click`,
      {
        x: Math.round(point.x),
        y: Math.round(point.y),
        button: point.button ?? "left",
      },
    );
    if (!res.ok) {
      throw new AgentComputerError(
        "COMMAND_FAILED",
        `Orgo /click failed on '${lease.instanceId}' (HTTP ${res.status}).`,
        "Verify coordinates and computer state.",
      );
    }
  }

  async mcpEndpoint(lease: ComputerLease, context: ProviderContext): Promise<ComputerMcpEndpoint | null> {
    const key = context.settings.orgoApiKey;
    if (!key) return null;
    return {
      kind: "rest-bridge",
      toolSurface: "orgo-computer",
      url: `${context.settings.orgoApiBaseUrl}/computers/${encodeURIComponent(lease.instanceId)}`,
      headers: {
        authorization: `Bearer ${key}`,
      },
      env: {
        ORGO_COMPUTER_ID: lease.instanceId,
      },
    };
  }

  async screenshotPreview(
    lease: ComputerLease,
    context: ProviderContext,
  ): Promise<ScreenshotPreview> {
    const res = await this.apiRequest(
      context,
      "GET",
      `/computers/${encodeURIComponent(lease.instanceId)}/screenshot`,
    );
    if (!res.ok) {
      throw new AgentComputerError(
        "COMMAND_FAILED",
        `Orgo /screenshot failed on '${lease.instanceId}' (HTTP ${res.status}).`,
        "Verify the Orgo Ubuntu desktop is running.",
      );
    }
    if (res.contentType.startsWith("image/")) {
      return {
        mimeType: res.contentType.includes("jpeg") ? "image/jpeg" : "image/png",
        base64Data: Buffer.from(res.bytes).toString("base64"),
        vncPreviewUrl: lease.vncPreviewUrl,
        capturedAt: context.now(),
      };
    }
    const payload = (res.body && typeof res.body === "object" ? res.body : {}) as {
      image?: string;
      screenshot?: string;
      data?: string;
    };
    return {
      mimeType: "image/png",
      base64Data: payload.image ?? payload.screenshot ?? payload.data ?? "",
      vncPreviewUrl: lease.vncPreviewUrl,
      capturedAt: context.now(),
    };
  }

  async pauseOrStop(
    lease: ComputerLease,
    context: ProviderContext,
  ): Promise<LeaseLifecycleResult> {
    const res = await this.apiRequest(
      context,
      "POST",
      `/computers/${encodeURIComponent(lease.instanceId)}/stop`,
      {},
    );
    if (!res.ok && res.status !== 404 && res.status !== 409) {
      throw new AgentComputerError(
        "PROVIDER_ERROR",
        `Failed to stop Orgo computer '${lease.instanceId}' (HTTP ${res.status}).`,
        "Check computer status in Orgo console.",
        502,
      );
    }
    return {
      state: "stopped",
      detail: `Stopped Orgo computer '${lease.instanceId}'.`,
    };
  }

  async destroyLease(
    lease: ComputerLease,
    context: ProviderContext,
  ): Promise<LeaseLifecycleResult> {
    const res = await this.apiRequest(
      context,
      "DELETE",
      `/computers/${encodeURIComponent(lease.instanceId)}`,
    );
    if (!res.ok && res.status !== 404 && res.status !== 410) {
      throw new AgentComputerError(
        "PROVIDER_ERROR",
        `Failed to delete Orgo computer '${lease.instanceId}' (HTTP ${res.status}).`,
        "Delete the computer in Orgo console.",
        502,
      );
    }
    return {
      state: "destroyed",
      detail: `Deleted Orgo computer '${lease.instanceId}'.`,
    };
  }
}

server/agent-computers/settings.ts:
/**
 * Runtime credential and API endpoint loader.
 * Reads strictly from process environment (injected via `keys run`); never reads `.env` files or serializes secret values.
 */
export interface AgentComputerRuntimeSettings {
  readonly cuaApiKey: string | null;
  readonly cuaApiBaseUrl: string;
  readonly daytonaApiKey: string | null;
  readonly daytonaApiBaseUrl: string;
  readonly orgoApiKey: string | null;
  readonly orgoApiBaseUrl: string;
}

export const DEFAULT_CUA_API_BASE_URL = "https://api.cua.ai/v1";
export const DEFAULT_DAYTONA_API_BASE_URL = "https://app.daytona.io/api";
export const DEFAULT_ORGO_API_BASE_URL = "https://www.orgo.ai/api";

function nonEmptySecret(value: string | undefined): string | null {
  const trimmed = value?.trim();
  return trimmed && trimmed.length > 0 ? trimmed : null;
}

function normalizeBaseUrl(raw: string | undefined, fallback: string): string {
  const candidate = raw?.trim();
  if (!candidate) return fallback;
  const parsed = new URL(candidate);
  if (parsed.protocol !== "https:" && parsed.protocol !== "http:") {
    throw new Error(`Unsupported API protocol ${parsed.protocol}`);
  }
  return candidate.replace(/\/+$/, "");
}

export function loadAgentComputerSettings(
  env: NodeJS.ProcessEnv = process.env,
): AgentComputerRuntimeSettings {
  return {
    cuaApiKey: nonEmptySecret(env.CUA_API_KEY),
    cuaApiBaseUrl: normalizeBaseUrl(env.CUA_API_URL, DEFAULT_CUA_API_BASE_URL),
    daytonaApiKey: nonEmptySecret(env.DAYTONA_API_KEY),
    daytonaApiBaseUrl: normalizeBaseUrl(env.DAYTONA_API_URL, DEFAULT_DAYTONA_API_BASE_URL),
    orgoApiKey: nonEmptySecret(env.ORGO_API_KEY),
    orgoApiBaseUrl: normalizeBaseUrl(env.ORGO_API_URL, DEFAULT_ORGO_API_BASE_URL),
  };
}

