import { existsSync, mkdirSync, readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { z } from "zod";
import {
  cloudBurstPolicySchema,
  computerLeaseSchema,
  mac2HostConfigSchema,
  type AgentComputerProviderId,
  type CloudBurstPolicy,
  type CloudBurstPolicyInput,
  type ComputerLease,
  type Mac2HostConfig,
  type Mac2HostConfigInput,
} from "../../shared/agent-computers.ts";
import { writeFileAtomic } from "../atomic.ts";

export const AGENT_COMPUTERS_FILENAME = "agent-computers.json";

const storeFileSchema = z
  .object({
    version: z.literal(1),
    mac2: mac2HostConfigSchema,
    burstPolicy: cloudBurstPolicySchema,
    leases: z.array(computerLeaseSchema).max(500),
  })
  .strict();

type StoreSnapshot = z.output<typeof storeFileSchema>;

function defaultStoreSnapshot(): StoreSnapshot {
  return {
    version: 1,
    mac2: mac2HostConfigSchema.parse({}),
    burstPolicy: cloudBurstPolicySchema.parse({}),
    leases: [],
  };
}

/**
 * Atomic JSON store at `<DATA_DIR>/agent-computers.json` (`0600`).
 * Stores only host routing parameters and non-secret lease records; API keys are never persisted here.
 */
export class AgentComputerStore {
  private readonly filePath: string;
  private state: StoreSnapshot;

  constructor(dataDirOrFilePath: string) {
    this.filePath = dataDirOrFilePath.endsWith(".json")
      ? dataDirOrFilePath
      : join(dataDirOrFilePath, AGENT_COMPUTERS_FILENAME);
    this.state = this.loadFromDisk();
  }

  private loadFromDisk(): StoreSnapshot {
    if (!existsSync(this.filePath)) {
      return defaultStoreSnapshot();
    }
    try {
      const parsed = JSON.parse(readFileSync(this.filePath, "utf8")) as unknown;
      return storeFileSchema.parse(parsed);
    } catch (error) {
      console.warn(
        `agent-computers: could not parse ${this.filePath}, starting with clean state: ${
          error instanceof Error ? error.message : String(error)
        }`,
      );
      return defaultStoreSnapshot();
    }
  }

  private saveToDisk(): void {
    mkdirSync(dirname(this.filePath), { recursive: true, mode: 0o700 });
    const serialized = `${JSON.stringify(this.state, null, 2)}\n`;
    writeFileAtomic(this.filePath, serialized, { mode: 0o600 });
  }

  path(): string {
    return this.filePath;
  }

  getMac2Config(): Mac2HostConfig {
    return { ...this.state.mac2 };
  }

  updateMac2Config(patch: Partial<Mac2HostConfigInput>): Mac2HostConfig {
    const merged = mac2HostConfigSchema.parse({ ...this.state.mac2, ...patch });
    this.state = { ...this.state, mac2: merged };
    this.saveToDisk();
    return { ...merged };
  }

  getBurstPolicy(): CloudBurstPolicy {
    return {
      ...this.state.burstPolicy,
      fallbackOrder: [...this.state.burstPolicy.fallbackOrder],
    };
  }

  updateBurstPolicy(patch: Partial<CloudBurstPolicyInput>): CloudBurstPolicy {
    const merged = cloudBurstPolicySchema.parse({ ...this.state.burstPolicy, ...patch });
    this.state = { ...this.state, burstPolicy: merged };
    this.saveToDisk();
    return this.getBurstPolicy();
  }

  listLeases(filter?: {
    agentId?: string;
    provider?: AgentComputerProviderId;
    includeDestroyed?: boolean;
  }): ComputerLease[] {
    return this.state.leases
      .filter((lease) => {
        if (!filter?.includeDestroyed && lease.state === "destroyed") return false;
        if (filter?.agentId && lease.agentId !== filter.agentId) return false;
        if (filter?.provider && lease.provider !== filter.provider) return false;
        return true;
      })
      .map((lease) => ({ ...lease }));
  }

  getLease(leaseId: string): ComputerLease | null {
    const found = this.state.leases.find((lease) => lease.leaseId === leaseId);
    return found ? { ...found } : null;
  }

  findPersistentLease(input: {
    provider: AgentComputerProviderId;
    instanceName: string;
  }): ComputerLease | null {
    const found = this.state.leases.find(
      (lease) =>
        lease.mode === "long-term" &&
        lease.provider === input.provider &&
        lease.instanceName === input.instanceName &&
        lease.state !== "destroyed",
    );
    return found ? { ...found } : null;
  }

  upsertLease(lease: ComputerLease): ComputerLease {
    const validated = computerLeaseSchema.parse(lease);
    const others = this.state.leases.filter((candidate) => candidate.leaseId !== validated.leaseId);
    // Prune destroyed ephemeral leases beyond recent 100 entries so the file stays compact.
    const activeOrPersistent = others.filter((candidate) => candidate.state !== "destroyed");
    const destroyedHistory = others.filter((candidate) => candidate.state === "destroyed").slice(-50);
    this.state = {
      ...this.state,
      leases: [...destroyedHistory, ...activeOrPersistent, validated],
    };
    this.saveToDisk();
    return { ...validated };
  }

  removeLease(leaseId: string): boolean {
    const before = this.state.leases.length;
    const remaining = this.state.leases.filter((candidate) => candidate.leaseId !== leaseId);
    if (remaining.length === before) return false;
    this.state = { ...this.state, leases: remaining };
    this.saveToDisk();
    return true;
  }
}

server/agent-computers/types.ts:
import { execFile } from "node:child_process";
import type {
  AgentComputerProviderId,
  CloudBurstPolicy,
  ComputerLease,
  ComputerLeaseRequest,
  ComputerLeaseState,
  ComputerMcpEndpoint,
  ComputerOsFamily,
  Mac2HostConfig,
  ProviderAvailability,
} from "../../shared/agent-computers.ts";
import type { AgentComputerRuntimeSettings } from "./settings.ts";

export interface ShellCommandOptions {
  timeoutMs?: number;
  env?: Record<string, string>;
  input?: string;
}

export interface ShellCommandOutput {
  exitCode: number;
  stdout: string;
  stderr: string;
}

export type ShellCommandRunner = (
  command: string,
  args: readonly string[],
  options?: ShellCommandOptions,
) => Promise<ShellCommandOutput>;

export type FetchLike = (input: string | URL, init?: RequestInit) => Promise<Response>;

export interface ProviderContext {
  readonly settings: AgentComputerRuntimeSettings;
  readonly mac2Config: Mac2HostConfig;
  readonly burstPolicy: CloudBurstPolicy;
  readonly activeLeases: readonly ComputerLease[];
  readonly fetchImpl: FetchLike;
  readonly runShell: ShellCommandRunner;
  readonly now: () => number;
}

export interface ProvisionedComputer {
  instanceId: string;
  instanceName: string;
  os: ComputerOsFamily;
  state: ComputerLeaseState;
  guestIp?: string | null;
  vncPreviewUrl?: string | null;
  snapshotName?: string | null;
}

export interface ExecCommandInput {
  command: string;
  cwd?: string;
  timeoutMs?: number;
}

export interface ExecCommandResult {
  ok: boolean;
  exitCode: number | null;
  stdout: string;
  stderr: string;
  durationMs: number;
}

export interface ScreenshotPreview {
  mimeType: "image/png" | "image/jpeg";
  base64Data: string;
  width?: number;
  height?: number;
  vncPreviewUrl?: string | null;
  capturedAt: number;
}

export interface LeaseLifecycleResult {
  state: ComputerLeaseState;
  snapshotName?: string | null;
  detail?: string;
}

/** Uniform contract implemented by local AX, 2nd Mac direct/Lume VM, Cua Cloud, Daytona, and Orgo providers. */
export interface ComputerProviderAdapter {
  readonly id: AgentComputerProviderId;
  checkAvailability(context: ProviderContext): Promise<ProviderAvailability>;
  provisionOrLease(request: ComputerLeaseRequest, context: ProviderContext): Promise<ProvisionedComputer>;
  execCommand(lease: ComputerLease, input: ExecCommandInput, context: ProviderContext): Promise<ExecCommandResult>;
  mcpEndpoint(lease: ComputerLease, context: ProviderContext): Promise<ComputerMcpEndpoint | null>;
  screenshotPreview(lease: ComputerLease, context: ProviderContext): Promise<ScreenshotPreview>;
  pauseOrStop(lease: ComputerLease, context: ProviderContext): Promise<LeaseLifecycleResult>;
  destroyLease(lease: ComputerLease, context: ProviderContext): Promise<LeaseLifecycleResult>;
}

/** Single-quotes an arbitrary shell string safely for `sh -c` or remote SSH invocation. */
export function shellQuote(value: string): string {
  return `'${value.replace(/'/g, "'\\''")}'`;
}

/** Wraps a remote command in a clean minimal environment so host daemon tokens never leak into guest processes. */
export function buildCleanRemoteShellCommand(command: string, cwd?: string): string {
  const body = cwd ? `cd ${shellQuote(cwd)} && ${command}` : command;
  return [
    "env -i",
    'HOME="${HOME:-/tmp}"',
    'USER="${USER:-agent}"',
    'PATH="/opt/homebrew/bin:/usr/local/bin:/usr/bin:/bin:/usr/sbin:/sbin"',
    'LANG="en_US.UTF-8"',
    "/bin/sh -c",
    shellQuote(body),
  ].join(" ");
}

const DEFAULT_SHELL_TIMEOUT_MS = 60_000;
const MAX_BUFFER_BYTES = 8 * 1024 * 1024;

export const defaultShellRunner: ShellCommandRunner = (command, args, options = {}) =>
  new Promise((resolve, reject) => {
    const child = execFile(
      command,
      [...args],
      {
        timeout: options.timeoutMs ?? DEFAULT_SHELL_TIMEOUT_MS,
        maxBuffer: MAX_BUFFER_BYTES,
        env: options.env
          ? { PATH: process.env.PATH ?? "/usr/bin:/bin", HOME: process.env.HOME ?? "/tmp", ...options.env }
          : { PATH: process.env.PATH ?? "/usr/bin:/bin", HOME: process.env.HOME ?? "/tmp" },
      },
      (error, stdout, stderr) => {
        if (!error) {
          resolve({ exitCode: 0, stdout: String(stdout), stderr: String(stderr) });
          return;
        }
        const coded = error as NodeJS.ErrnoException & { killed?: boolean; signal?: string | null };
        if (typeof coded.code === "number") {
          resolve({ exitCode: coded.code, stdout: String(stdout), stderr: String(stderr) });
          return;
        }
        reject(error);
      },
    );
    if (options.input !== undefined && child.stdin) {
      child.stdin.end(options.input);
    }
  });

